  const $ = id => document.getElementById(id);

  // App focado só em Manutenção (ordenha, resfriador e conforto animal): Veterinária,
  // Qualidade do leite, Nutrição e Comercial ficam desligados para todos e somem do app.
  // Os dados deles continuam guardados no banco. Para trazer de volta, troque para false
  // (aí volta a valer o "Módulos ativos" da Administração).
  const SO_MANUTENCAO = true;

  // Versão que aparece no fim do menu "Mais". Troque a cada atualização publicada:
  // quando alguém disser que "deu erro", dá para saber qual versão a pessoa está usando.
  const APP_VERSAO = '2026.11.27.3';

  // ================= confirmação e avisos =================
  // Dentro do Claude o app roda num quadro protegido, e o navegador IGNORA
  // confirm() e alert() (confirm sempre responde "cancelar"). Por isso o app
  // usa a própria caixinha: confirmar(...) devolve true/false, avisar(...) só informa.
  let dialogoResolver = null;
  function abrirDialogo(msg, { ok = 'OK', cancelar = null, perigo = false } = {}) {
    if (dialogoResolver) { const r = dialogoResolver; dialogoResolver = null; r(false); }
    $('dialogo-msg').textContent = msg;
    const okBtn = $('dialogo-ok');
    okBtn.textContent = ok;
    okBtn.classList.toggle('perigo', perigo);
    $('dialogo-cancelar').hidden = !cancelar;
    if (cancelar) $('dialogo-cancelar').textContent = cancelar;
    $('dialogo').hidden = false;
    okBtn.focus();
    return new Promise(resolve => { dialogoResolver = resolve; });
  }
  function fecharDialogo(resposta) {
    $('dialogo').hidden = true;
    const r = dialogoResolver;
    dialogoResolver = null;
    if (r) r(resposta);
  }
  $('dialogo-ok').addEventListener('click', () => fecharDialogo(true));
  $('dialogo-cancelar').addEventListener('click', () => fecharDialogo(false));
  $('dialogo').addEventListener('click', (e) => { if (e.target === $('dialogo')) fecharDialogo(false); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && !$('dialogo').hidden) fecharDialogo(false); });
  function confirmar(msg, textoOk = 'Excluir') {
    return abrirDialogo(msg, { ok: textoOk, cancelar: 'Cancelar', perigo: true });
  }
  function avisar(msg) {
    return abrirDialogo(msg, { ok: 'OK' });
  }

  // ================= router =================
  const VIEWS = ['entrada', 'p-login', 'p-inicio', 'p-prop', 'p-qual', 'p-prat', 'p-cham', 'admin', 'home', 'setor', 'mais', 'encaminhamentos', 'ordens', 'preventivas', 'calctec', 'estoque', 'painel', 'calc', 'historico', 'produtores', 'produtor', 'leite', 'medias', 'pmls', 'rota', 'vendas', 'venda-form', 'venda', 'orcamento'];
  // qual aba da barra de baixo fica acesa em cada tela
  const TAB_DA_VIEW = {
    entrada: 'home', admin: 'mais', home: 'home', calc: 'mais', historico: 'mais', produtores: 'visitas', produtor: 'visitas', rota: 'visitas',
    leite: 'home', medias: 'home', pmls: 'home', vendas: 'mais', 'venda-form': 'mais', venda: 'mais', orcamento: 'mais',
    encaminhamentos: 'mais', mais: 'mais', ordens: 'ordens', preventivas: 'ordens', calctec: 'home', estoque: 'home', painel: 'mais'
  };
  function showView(name) {
    // sem acesso liberado, a única tela é a de entrada
    if (name !== 'entrada' && acesso && acesso.estado !== 'ativo') name = 'entrada';
    VIEWS.forEach(v => { $('view-' + v).hidden = (v !== name); });
    $('fab-add-produtor').hidden = (name !== 'produtores');
    document.body.dataset.view = name;
    const abaDaBarra = name === 'setor' ? (setorAberto === 'comercial' ? 'mais' : 'home') : name === 'calctec' && ctVoltar === 'mais' ? 'mais' : name === 'estoque' && esVoltar === 'mais' ? 'mais' : TAB_DA_VIEW[name];
    document.querySelectorAll('.tab').forEach(t => {
      const ativa = t.dataset.tab === abaDaBarra;
      t.classList.toggle('ativa', ativa);
      if (ativa) t.setAttribute('aria-current', 'page'); else t.removeAttribute('aria-current');
    });
    const tela = $('view-' + name);
    tela.classList.remove('view-entrando');
    void tela.offsetWidth; // reinicia a animação
    tela.classList.add('view-entrando');
    window.scrollTo(0, 0);
    // voltar para a ficha (de uma venda, da calculadora…) reabre a aba em que a pessoa estava
    if (name === 'produtor' && currentProdutorId) ativarAbaFicha(abaFicha);
    if (name === 'setor') renderSetor();
    if (name === 'ordens') renderOrdens();
    if (name === 'preventivas') renderPreventivas();
    if (name === 'home') renderHomeManut();
    atualizarTopo(name);
    apAoMostrar(name);
  }
  $('nav-calc').addEventListener('click', () => showView('calc'));
  $('nav-visitas').addEventListener('click', () => showView('produtores'));
  $('back-calc').addEventListener('click', () => { if (podeVerSetor('comercial')) abrirSetor('comercial'); else showView('home'); });
  $('back-produtores').addEventListener('click', () => showView('home'));
  $('btn-ver-historico').addEventListener('click', () => showView('historico'));
  $('back-historico').addEventListener('click', () => showView('calc'));

  // ================= identidade (conta Claude do visitante) =================
  // Sem senha: quem abre este link já é identificado pela própria conta Claude
  // (isso é o que preenche o nome/avatar abaixo). Quem pode ver ou editar o app
  // é controlado pelo botão de compartilhar do artefato, não por uma senha aqui.
  let viewerId = null;
  let viewerName = '';
  async function renderGreeting() {
    try {
      const user = await claude.use('user');
      if (user) {
        const me = await user.me();
        viewerId = me.id;
        viewerName = me.name || '';
        $('greeting-text').textContent = viewerName ? ('Olá, ' + viewerName + '!') : 'Olá!';
        return;
      }
    } catch (e) {}
    $('greeting-text').textContent = 'Olá!';
  }

  // ================= banco de dados compartilhado + fila de envio =================
  // Tudo o que o app grava passa por gravar(). Ele tenta mandar para o banco na hora;
  // se estiver sem sinal, guarda o registro numa fila NESTE aparelho e envia sozinho
  // quando a conexão voltar. Cada registro novo já nasce com um id próprio, então
  // reenviar nunca cria cópia: o mesmo id só sobrescreve a si mesmo.
  let dbReady = false;
  let dbRef = null;
  const DEMO_CHAVE = 'auriverde_demo';
  const DEMO_ATIVO = (() => { try { return localStorage.getItem(DEMO_CHAVE) === '1'; } catch (e) { return false; } })();
  const DEMO_COLECOES = ['produtores', 'ordens', 'encaminhamentos', 'vendas', 'calculos', 'sistema', 'atividades', 'estoque', 'orcamentos', 'avisos', 'avisos-tecnicos', 'anotacoes', 'agenda-tokens'];
  function caminhoFisico(c) {
    if (!DEMO_ATIVO) return c;
    const i = c.indexOf('/'), raiz = i < 0 ? c : c.slice(0, i);
    return DEMO_COLECOES.includes(raiz) ? 'demo_' + c : c;
  }
  function envolverDemo(db) { return { doc: c => db.doc(caminhoFisico(c)), collection: c => db.collection(caminhoFisico(c)) }; }
  let dbBruto = null;          // o banco sem o desvio da demonstração (só para criar/apagar os dados demo_*)
  const FILA_KEY = DEMO_ATIVO ? 'auriverde_demo_fila_envio' : 'auriverde_fila_envio';
  const ESPELHO_PREFIXO = DEMO_ATIVO ? 'auriverde_demo_espelho_' : 'auriverde_espelho_';
  let fila = [];               // [{id, tipo: 'set'|'update'|'delete', caminho, dados, em}]
  let enviandoFila = false;
  let opEmEnvio = null;        // id da operação que está indo para o banco agora
  let filaTravada = false;     // true depois de uma falha de conexão, até a fila esvaziar
  let timerFila = null;
  let dbDecidido = false;     // só mostra aviso de conexão depois de saber se o banco respondeu
  const esperasFila = {};      // id da operação → quem está esperando ela sair da fila
  const recentes = [];         // operações recém-enviadas: continuam valendo por alguns segundos na tela

  function lerLS(k, padrao) { try { const r = localStorage.getItem(k); return r == null ? padrao : JSON.parse(r); } catch (e) { return padrao; } }
  function gravarLS(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); return true; } catch (e) { return false; } }
  function apagarLS(k) { try { localStorage.removeItem(k); } catch (e) {} }
  function novoId() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
  const clonar = o => (o == null ? o : JSON.parse(JSON.stringify(o)));
  // mesma regra do update do banco: objetos se juntam campo a campo; o resto (listas incluídas) substitui
  function mesclar(alvo, fonte) {
    for (const k in fonte) {
      const v = fonte[k];
      if (v && typeof v === 'object' && !Array.isArray(v) && alvo[k] && typeof alvo[k] === 'object' && !Array.isArray(alvo[k])) mesclar(alvo[k], v);
      else alvo[k] = clonar(v);
    }
    return alvo;
  }
  const colecaoDe = caminho => caminho.split('/').slice(0, -1).join('/');
  const idDe = caminho => caminho.split('/').pop();

  function carregarFila() { const f = lerLS(FILA_KEY, []); fila = Array.isArray(f) ? f.filter(o => o && o.caminho && o.tipo) : []; }
  let filaSoNaMemoria = false;  // o aparelho não teve espaço para guardar a fila (fotos grandes)
  function salvarFila() { filaSoNaMemoria = !gravarLS(FILA_KEY, fila) && fila.length > 0; renderAvisoFila(); }
  function resolverOp(id, resultado) {
    (esperasFila[id] || []).forEach(f => { try { f(resultado); } catch (e) {} });
    delete esperasFila[id];
  }

  function enfileirar(tipo, caminho, dados) {
    let ult = null;
    for (let i = fila.length - 1; i >= 0; i--) if (fila[i].caminho === caminho) { ult = fila[i]; break; }
    // várias mudanças seguidas no mesmo registro viram uma só (o resultado final é o mesmo)
    if (ult && ult.id !== opEmEnvio && tipo === 'update' && ult.tipo !== 'delete') {
      mesclar(ult.dados, dados || {});
      salvarFila();
      return ult.id;
    }
    const herdadas = [];
    if (tipo !== 'update') {
      fila = fila.filter(o => {
        const sai = o.caminho === caminho && o.id !== opEmEnvio;
        if (sai && esperasFila[o.id]) { herdadas.push(...esperasFila[o.id]); delete esperasFila[o.id]; }
        return !sai;
      });
    }
    const op = { id: novoId(), tipo, caminho, dados: tipo === 'delete' ? null : clonar(dados || {}), em: Date.now() };
    fila.push(op);
    if (herdadas.length) esperasFila[op.id] = herdadas;
    salvarFila();
    return op.id;
  }

  // Grava (ou guarda na fila). Devolve uma Promise que resolve {enviado: true} quando o
  // banco confirmou, ou {enviado: false, naFila: true} quando ficou guardado para depois.
  function gravar(tipo, caminho, dados) {
    const id = enfileirar(tipo, caminho, dados);
    const espera = new Promise(res => { (esperasFila[id] = esperasFila[id] || []).push(res); });
    reentregar(colecaoDe(caminho));
    if (!dbRef || filaTravada) resolverOp(id, { enviado: false, naFila: true });
    enviarFila();
    return espera;
  }

  function executarOp(op) {
    const ref = dbRef.doc(op.caminho);
    if (op.tipo === 'set') return ref.set(op.dados);
    if (op.tipo === 'update') return ref.update(op.dados);
    return ref.delete();
  }
  function comPrazo(p, ms) {
    let t;
    return Promise.race([p, new Promise((_, rej) => { t = setTimeout(() => rej({ code: 'timeout' }), ms); })])
      .finally(() => clearTimeout(t));
  }
  // Erros que não se resolvem tentando de novo: o registro sai da fila (e a pessoa é avisada quando faz sentido).
  const ERROS_DEFINITIVOS = ['invalid_argument', 'quota_exceeded', 'transform_error'];
  function avisarRecusa(op, code) {
    if (op.caminho.startsWith('data/users/')) return; // rota pessoal de outra conta neste aparelho
    if (/^(atividades|acessos|solicitacoes)\//.test(op.caminho)) return; // registro interno / pedido (quem pediu já foi avisado)
    if (op.caminho.startsWith('usuarios/') && op.caminho === 'usuarios/' + viewerId && souDono) return;
    if (op.caminho.startsWith('usuarios/')) {
      avisar('Para aprovar pessoas e mudar acessos você também precisa ser Editor no botão Compartilhar do app. A mudança não foi salva.');
      return;
    }
    if (op.caminho.startsWith('config/')) {
      avisar('Só quem é Editor do app pode alterar as configurações. A mudança não foi salva.');
      return;
    }
    if (code === 'quota_exceeded') {
      avisar('O banco do app está cheio e não aceitou um registro novo. Exclua registros antigos que não precisa mais e lance de novo.');
      return;
    }
    // update/exclusão de algo que outra pessoa já apagou: não há o que salvar
    if (op.tipo === 'set') avisar('Um registro não pôde ser salvo no banco e foi descartado. Confira e lance de novo se precisar.');
  }

  async function enviarFila() {
    clearTimeout(timerFila);
    if (enviandoFila) return;
    if (!dbRef || !fila.length) {
      if (!fila.length) filaTravada = false;
      renderAvisoFila();
      agendarReenvio();
      return;
    }
    enviandoFila = true;
    renderAvisoFila();
    let falhou = false;
    while (fila.length && dbRef) {
      const op = fila[0];
      opEmEnvio = op.id;
      let resultado = { enviado: true };
      try {
        await comPrazo(executarOp(op), 15000);
      } catch (e) {
        const code = (e && e.code) || 'unavailable';
        if (ERROS_DEFINITIVOS.includes(code)) { resultado = { enviado: false, recusado: code }; avisarRecusa(op, code); }
        else falhou = true;  // sem sinal, banco ocupado, demorou demais… fica na fila
      }
      opEmEnvio = null;
      if (falhou) break;
      fila = fila.filter(o => o.id !== op.id);
      if (resultado.enviado) recentes.push({ ...op, ate: Date.now() + 6000 });
      salvarFila();
      resolverOp(op.id, resultado);
      if (resultado.recusado) reentregar(colecaoDe(op.caminho));
    }
    enviandoFila = false;
    filaTravada = falhou && fila.length > 0;
    if (filaTravada) fila.forEach(o => resolverOp(o.id, { enviado: false, naFila: true }));
    renderAvisoFila();
    agendarReenvio();
  }
  function agendarReenvio() {
    clearTimeout(timerFila);
    if (fila.length && dbRef) timerFila = setTimeout(enviarFila, 20000);
  }
  window.addEventListener('online', () => enviarFila());
  $('fila-enviar').addEventListener('click', () => enviarFila());
  document.addEventListener('visibilitychange', () => { if (!document.hidden) enviarFila(); });

  function renderAvisoFila() {
    const box = $('offline-note');
    if (!box) return;
    // registros internos (atividades, último acesso) não entram na conta que a pessoa vê
    const n = fila.filter(o => !/^(atividades|acessos)\//.test(o.caminho)).length;
    const mostrar = dbDecidido && (!dbRef || (n > 0 && filaTravada));
    box.hidden = !mostrar;
    if (!mostrar) return;
    const qtd = n + (n === 1 ? ' registro aguardando envio' : ' registros aguardando envio');
    let txt;
    if (!dbRef) {
      txt = n ? '⏳ ' + qtd + '. Sem conexão com o banco compartilhado: eles vão na próxima vez que o app abrir com internet.'
              : 'Sem conexão com o banco compartilhado agora. O que você lançar fica guardado neste aparelho e é enviado quando a conexão voltar.';
    } else {
      txt = '⏳ ' + qtd + (enviandoFila ? ' — enviando…' : '. Vão sozinhos quando a conexão voltar.');
    }
    if (n && filaSoNaMemoria) txt += ' Não feche o app até enviar: não coube tudo na memória do aparelho.';
    $('fila-texto').textContent = txt;
    $('fila-enviar').hidden = !n || !dbRef || enviandoFila;
  }

  // ---- leitura: o que veio do banco + o que ainda está na fila por cima ----
  const brutos = {};        // coleção → documentos como vieram do banco (ou do espelho deste aparelho)
  const doBanco = {};       // coleção → nº de assinaturas vivas que já receberam algo do banco
  const entregadores = {};  // coleção → funções que redesenham quem usa essa coleção

  function opsDaColecao(colecao) {
    const agora = Date.now();
    for (let i = recentes.length - 1; i >= 0; i--) if (recentes[i].ate < agora) recentes.splice(i, 1);
    return recentes.concat(fila).filter(o => colecaoDe(o.caminho) === colecao);
  }
  function sobreporFila(colecao, docs) {
    const lista = docs.slice();
    opsDaColecao(colecao).forEach(op => {
      const id = idDe(op.caminho);
      const i = lista.findIndex(d => d.id === id);
      if (op.tipo === 'delete') { if (i >= 0) lista.splice(i, 1); }
      else if (op.tipo === 'set') { const d = { ...clonar(op.dados), id }; if (i >= 0) lista[i] = d; else lista.push(d); }
      else if (i >= 0) lista[i] = mesclar(clonar(lista[i]), op.dados);
    });
    return lista;
  }
  function espelhar(colecao) { gravarLS(ESPELHO_PREFIXO + colecao, brutos[colecao] || []); }
  function brutosDe(colecao) {
    if (!brutos[colecao]) { const e = lerLS(ESPELHO_PREFIXO + colecao, []); brutos[colecao] = Array.isArray(e) ? e : []; }
    return brutos[colecao];
  }
  function listaAtual(colecao, ordenar) {
    const l = sobreporFila(colecao, brutosDe(colecao));
    if (ordenar) l.sort(ordenar);
    return l;
  }
  function reentregar(colecao) { (entregadores[colecao] || []).slice().forEach(f => f()); }

  // Assina uma coleção: entrega já o que há neste aparelho e depois cada mudança do banco.
  // aoReceber(lista, confiavel): confiavel = a lista já veio do banco (ou não há banco nesta visita).
  function assinar(colecao, aoReceber, ordenar) {
    let vivo = true, desligar = null, timer = null, recebeu = false;
    const entregar = () => { if (vivo) aoReceber(listaAtual(colecao, ordenar), recebeu || !dbRef); };
    (entregadores[colecao] = entregadores[colecao] || []).push(entregar);
    const ligar = () => {
      if (!vivo || !dbRef) return;
      try {
        desligar = dbRef.collection(colecao).onSnapshot(snap => {
          brutos[colecao] = snap.docs.map(d => ({ ...d.data(), id: d.id }));
          if (!recebeu) { recebeu = true; doBanco[colecao] = (doBanco[colecao] || 0) + 1; }
          espelhar(colecao);
          entregar();
          // o banco respondeu de verdade: boa hora para mandar o que ficou na fila
          if (filaTravada && !(snap.metadata && snap.metadata.fromCache)) enviarFila();
        }, (err) => {
          desligar = null;
          const code = err && err.code;
          if (vivo && code !== 'revoked' && code !== 'invalid_argument') timer = setTimeout(ligar, 10000);
        });
      } catch (e) {}
    };
    entregar();
    ligar();
    return () => {
      vivo = false; clearTimeout(timer);
      if (desligar) { try { desligar(); } catch (e) {} }
      if (recebeu) doBanco[colecao] = Math.max(0, (doBanco[colecao] || 1) - 1);
      entregadores[colecao] = (entregadores[colecao] || []).filter(f => f !== entregar);
    };
  }
  // Leitura única (listas que o app não acompanha ao vivo, como as médias de cada produtor)
  async function lerColecao(colecao) {
    if (dbRef && !doBanco[colecao]) {
      try {
        const snap = await comPrazo(dbRef.collection(colecao).get(), 12000);
        brutos[colecao] = snap.docs.map(d => ({ ...d.data(), id: d.id }));
        espelhar(colecao);
      } catch (e) {}
    }
    return sobreporFila(colecao, brutosDe(colecao));
  }

  // Versões antigas guardavam neste aparelho o que era feito sem banco (cada tipo numa chave).
  // Agora tudo passa pela fila: o que sobrou lá vai para o banco uma vez, com o mesmo id.
  function migrarDadosLocaisAntigos() {
    const mover = (chave, colecao, completar) => {
      const lista = lerLS(chave, null);
      if (lista === null) return;
      if (Array.isArray(lista)) {
        lista.forEach(item => {
          if (!item || !item.id) return;
          const { id, ...dados } = item;
          enfileirar('set', colecao + '/' + id, completar ? completar(dados) : dados);
        });
      }
      apagarLS(chave);
    };
    mover('margem_brands', 'empresas', d => ({ createdAt: Date.now(), ...d }));
    mover('auriverde_produtores', 'produtores');
    mover('auriverde_calculos', 'calculos');
    mover('auriverde_vendas', 'vendas');
    const chaves = [];
    try { for (let i = 0; i < localStorage.length; i++) chaves.push(localStorage.key(i)); } catch (e) {}
    chaves.forEach(k => {
      if (!k) return;
      if (k.startsWith('auriverde_visitas_')) mover(k, 'produtores/' + k.slice('auriverde_visitas_'.length) + '/visitas');
      else if (k.startsWith('auriverde_medias_')) mover(k, 'produtores/' + k.slice('auriverde_medias_'.length) + '/medias');
    });
  }

  async function prepararBanco() {
    carregarFila();
    migrarDadosLocaisAntigos();
    let db = null;
    try { db = await claude.use('db'); } catch (e) { db = null; }
    dbBruto = db || null;
    dbRef = db ? (DEMO_ATIVO ? envolverDemo(db) : db) : null;
    dbReady = !!dbRef;
    dbDecidido = true;
    renderAvisoFila();
  }
  // Os dados só começam a chegar depois que o acesso da pessoa foi liberado.
  var produtoresTodos = [], vendasTodas = [], orcamentosTodos = [], verArquivados = false;
  function escoparVendas(l) {
    if (!podeVer('vendas')) return [];
    let v = l.filter(x => naoArquivado(x) && !x.cancelada);
    if (acesso.soProprias && !ehAdmin()) v = v.filter(x => x.criadoPor && x.criadoPor === viewerId);
    return v;
  }
  // canceladas (a OS foi cancelada): aparecem na lista, riscadas, e não entram em nenhuma conta
  function vendasCanceladas() {
    if (!podeVer('vendas')) return [];
    let v = vendasTodas.filter(x => x.cancelada && !x.arquivado);
    if (acesso.soProprias && !ehAdmin()) v = v.filter(x => x.criadoPor === viewerId);
    return v;
  }
  // de onde a venda veio (as antigas são manuais)
  function rotuloOrigemVenda(v) {
    return v.origem === 'os' ? numOS(v.osNumero) : v.origem === 'orcamento' ? 'Orçamento' + (Number(v.orcamentoNumero) > 0 ? ' nº ' + v.orcamentoNumero : '') : numVenda(v.numero);
  }
  function iniciarDados() {
    if (dadosIniciados) return;
    dadosIniciados = true;
    assinar('empresas', l => { brands = l; renderBrands(); }, (a, b) => (a.name || '').localeCompare(b.name || ''));
    assinar('produtores', l => { produtoresTodos = l; produtores = verArquivados ? l : l.filter(naoArquivado); renderProdutoresList(); renderResumoHome(); });
    assinar('calculos', l => { calculos = l.filter(naoArquivado); renderHistorico(); }, (a, b) => (b.criadoEm || 0) - (a.criadoEm || 0));
    assinar('vendas', l => { vendasTodas = l; vendas = escoparVendas(l); aoMudarVendas(); renderResumoHome(); }, (a, b) => (b.data || '').localeCompare(a.data || ''));
    assinar('orcamentos', l => { orcamentosTodos = l; aoMudarOrcamentos(); });
    assinar('anotacoes', l => { anotacoesTodas = l; renderListaAnotacoes(); });
    assinar('config', l => aplicarConfig(l));
    iniciarEncaminhamentos();
    iniciarOrdens();
    renderAvisoFila();
    enviarFila();
    iniciarPermissaoConfig();
    iniciarRota();
    setTimeout(guardarTabelasNoAparelho, 4000);
  }

  // ================= configurações compartilhadas =================
  // Um documento só (config/geral) com ICMS, margem padrão, comissão e os limites do PMLS.
  // Todo mundo lê; só quem é Editor do app (no botão Compartilhar) consegue gravar —
  // a regra está no próprio banco, então não depende só da tela.
  const CONFIG_PADRAO = { icmsDentro: 18, icmsFora: 12, margemPadrao: 17, comissaoPct: 5, comissaoBase: 'venda', limiteCCS: 500, limiteCPP: 300, osViraVenda: true, agendaMaxDia: 5, agendaDias: [1, 2, 3, 4, 5] };
  let config = { ...CONFIG_PADRAO };
  let podeEditarConfig = null; // null = ainda não se sabe (o banco decide na hora de gravar)
  function aplicarConfig(docs) {
    aplicarModulos(docs.find(d => d.id === 'modulos'));
    try { aplicarConfigPrev(docs.find(d => d.id === 'preventiva')); } catch (e) {}
    const antigo = docs.find(d => d.id === 'vendas') || {};   // versão anterior guardava só a comissão aqui
    const geral = docs.find(d => d.id === 'geral') || {};
    const novo = { ...CONFIG_PADRAO };
    if (antigo.comissaoPct != null) novo.comissaoPct = Number(antigo.comissaoPct);
    if (antigo.comissaoBase) novo.comissaoBase = antigo.comissaoBase;
    Object.keys(CONFIG_PADRAO).forEach(k => {
      if (geral[k] == null || geral[k] === '') return;
      novo[k] = k === 'comissaoBase' ? geral[k] : k === 'osViraVenda' ? geral[k] !== false
        : k === 'agendaDias' ? (Array.isArray(geral[k]) && geral[k].length ? geral[k].map(Number) : CONFIG_PADRAO.agendaDias) : Number(geral[k]);
    });
    novo.atualizadoPor = geral.atualizadoPor || null;
    novo.atualizadoEm = geral.atualizadoEm || null;
    const margemAntes = config.margemPadrao;
    config = novo;
    aoMudarConfig(margemAntes);
  }
  async function iniciarPermissaoConfig() {
    try {
      const user = await claude.use('user');
      podeEditarConfig = user ? await user.canEdit() : null;
    } catch (e) { podeEditarConfig = null; }
    if (typeof atualizarBotaoImportar === 'function') atualizarBotaoImportar();
  }
  function numTxt(n) { return n == null || n === '' ? '' : String(n).replace('.', ','); }

  // Números digitados no padrão brasileiro (vírgula ou ponto). Mesmo leitor do dinheiro.
  function parseNum(v) { return parseMoney(v); }
  // Valor em reais digitado no padrão brasileiro: ponto = milhar, vírgula = centavos.
  // "1.234,56" → 1234.56 · "1234,56" → 1234.56 · "1.234" → 1234 · "12.5" → 12.5
  function parseMoney(v) {
    let s = String(v == null ? '' : v).replace(/\s/g, '').replace(/^R\$/i, '');
    if (s.includes(',')) {
      s = s.replace(/\./g, '').replace(',', '.');
    } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
      s = s.replace(/\./g, '');
    }
    const n = parseFloat(s);
    return isNaN(n) ? 0 : n;
  }
  function fmtDate(iso) {
    if (!iso) return '';
    const [y, m, d] = iso.split('-');
    return d + '/' + m + '/' + y;
  }
  function todayISO() {
    const d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  }
  // Soma meses a uma data AAAA-MM-DD sem "estourar" o mês:
  // 31/08 + 6 meses = 28/02 (ou 29/02), nunca 03/03.
  function addMonthsISO(iso, months) {
    if (!iso) return '';
    const [y, m, d] = iso.split('-').map(Number);
    const alvo = new Date(y, (m - 1) + months, 1);
    const ultimoDia = new Date(alvo.getFullYear(), alvo.getMonth() + 1, 0).getDate();
    return alvo.getFullYear() + '-' + String(alvo.getMonth() + 1).padStart(2, '0') + '-' + String(Math.min(d, ultimoDia)).padStart(2, '0');
  }
  const MESES_ATE_REVISAO = 6;
  const REVISAO_ALERTA_DIAS = 15; // "vence em breve" = próximos 15 dias
  function diasAte(iso) {
    const [y, m, d] = iso.split('-').map(Number);
    const t = new Date();
    const hoje = new Date(t.getFullYear(), t.getMonth(), t.getDate());
    return Math.round((new Date(y, m - 1, d) - hoje) / 86400000);
  }
  // Texto + cor da próxima revisão: vencida (vermelho), até 15 dias (amarelo), ok (cinza)
  function proximaStatus(iso) {
    const dias = diasAte(iso);
    if (dias < 0) return { cls: 'vencida', txt: 'Revisão vencida desde ' + fmtDate(iso) };
    if (dias === 0) return { cls: 'breve', txt: 'Próxima revisão: hoje (' + fmtDate(iso) + ')' };
    if (dias <= REVISAO_ALERTA_DIAS) return { cls: 'breve', txt: 'Próxima revisão: ' + fmtDate(iso) + ' (em ' + dias + (dias === 1 ? ' dia)' : ' dias)') };
    return { cls: 'ok', txt: 'Próxima revisão: ' + fmtDate(iso) };
  }
  function temRevisao(v) {
    return v.categoria === 'ordenha' && !!v.revisao && revisaoTemAlgo(v.revisao.itens);
  }
  function ultimaRevisaoDe(lista) {
    return lista.filter(osConcluida).slice().sort((a, b) => (b.data || '').localeCompare(a.data || '')).find(temRevisao) || null;
  }

  // =====================================================
  // CALCULADORA DE MARGEM
  // =====================================================
  const produtoEl = document.getElementById('calc-produto');
  const custoEl = document.getElementById('custo');
  const btnDentro = document.getElementById('btn-dentro');
  const btnFora = document.getElementById('btn-fora');
  const margemEl = document.getElementById('margem-auriverde');
  const chipRow = document.getElementById('brand-chips');
  const brandNameEl = document.getElementById('brand-name');
  const brandOriginToggle = document.getElementById('brand-origin-toggle');
  const brandAddBtn = document.getElementById('brand-add-btn');

  let origem = 'dentro';
  let brands = [];
  let selectedBrandId = null;
  let newBrandOrigem = 'dentro';

  function renderBrands() {
    chipRow.innerHTML = '';
    brands.forEach(b => {
      const chip = document.createElement('span');
      chip.className = 'chip origem-' + b.origem + (b.id === selectedBrandId ? ' selected' : '');
      chip.innerHTML = '<span class="dot"></span><span class="name"></span><span class="x">×</span>';
      chip.querySelector('.name').textContent = b.name;
      chip.querySelector('.x').dataset.perm = 'admin'; // excluir marca é do Administrador
      chip.querySelector('.name').addEventListener('click', () => {
        selectedBrandId = b.id;
        setOrigem(b.origem);
        renderBrands();
      });
      chip.querySelector('.x').addEventListener('click', (e) => {
        e.stopPropagation();
        confirmar('Excluir a marca "' + b.name + '"?').then(ok => { if (ok) removeBrand(b.id); });
      });
      chipRow.appendChild(chip);
    });
  }
  // grava a marca e devolve o id (o "+" das marcas e o catálogo, nas vendas, usam esta)
  function criarMarca(name, origemVal) {
    const id = novoId();
    gravar('set', 'empresas/' + id, { name, origem: origemVal, createdAt: Date.now(), criadoPor: viewerId || null });
    return id;
  }
  function addBrand(name, origemVal) {
    const id = criarMarca(name, origemVal);
    selectedBrandId = id;
    setOrigem(origemVal);
    renderBrands();
  }
  function removeBrand(id) {
    if (selectedBrandId === id) selectedBrandId = null;
    gravar('delete', 'empresas/' + id);
  }
  brandOriginToggle.querySelectorAll('button').forEach(btn => {
    btn.addEventListener('click', () => {
      newBrandOrigem = btn.dataset.o;
      brandOriginToggle.querySelectorAll('button').forEach(b => b.classList.toggle('active', b === btn));
    });
  });
  brandAddBtn.addEventListener('click', () => {
    const name = brandNameEl.value.trim();
    if (!name) return;
    addBrand(name, newBrandOrigem);
    brandNameEl.value = '';
  });
  brandNameEl.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') brandAddBtn.click();
  });

  function setOrigem(o) {
    origem = o;
    btnDentro.classList.toggle('active', o === 'dentro');
    btnFora.classList.toggle('active', o === 'fora');
    calcular();
  }
  btnDentro.addEventListener('click', () => { selectedBrandId = null; renderBrands(); setOrigem('dentro'); });
  btnFora.addEventListener('click', () => { selectedBrandId = null; renderBrands(); setOrigem('fora'); });

  function fmt(n) {
    return 'R$ ' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  function fmtPct(n) {
    return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
  }
  function fmtMult(n) {
    return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '× o custo';
  }

  function saveCalcState() {
    try {
      localStorage.setItem('margem_state', JSON.stringify({
        produto: produtoEl.value,
        custo: custoEl.value,
        origem,
        selectedBrandId
      }));
    } catch (e) {}
  }
  function loadCalcState() {
    try {
      const raw = localStorage.getItem('margem_state');
      if (!raw) return;
      const s = JSON.parse(raw);
      if (s.produto) produtoEl.value = s.produto;
      if (s.custo) custoEl.value = s.custo;
      if (s.selectedBrandId) selectedBrandId = s.selectedBrandId;
      if (s.origem) setOrigem(s.origem);
    } catch (e) {}
  }
  produtoEl.addEventListener('input', saveCalcState);

  function calcular() {
    const custo = parseMoney(custoEl.value);
    const aliquota = aliquotaDaOrigem(origem);
    // Tabela da empresa: cada 1 ponto de margem equivale a 0,01 no divisor,
    // na direção oposta (17% = 0,63, 18% = 0,62, 16% = 0,64).
    const margemAuriverde = margemDoCalculo();
    const divisor = (80 - margemAuriverde) / 100;

    const valorIcms = custo * (aliquota / 100);
    const custoLiquido = custo - valorIcms;
    const preco = precoVendaDoItem({ custo, origem }, margemAuriverde);
    const lucro = preco - custo;
    const margem = preco > 0 ? (lucro / preco) * 100 : 0;
    const markup = custo > 0 ? (lucro / custo) * 100 : 0;
    const multiplicador = custo > 0 ? preco / custo : 0;

    document.getElementById('out-preco').textContent = fmt(preco);
    document.getElementById('out-icms').textContent = fmt(valorIcms);
    document.getElementById('out-liquido').textContent = fmt(custoLiquido);
    document.getElementById('out-lucro').textContent = fmt(lucro);
    document.getElementById('out-margem').textContent = fmtPct(margem);
    document.getElementById('out-markup').textContent = fmtPct(markup);
    document.getElementById('out-mult').textContent = fmtMult(multiplicador);
    document.getElementById('out-margem-auriverde').textContent = fmtPct(margemAuriverde);
    document.getElementById('divisor-hint').textContent = '= divisor ' + divisor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' (tabela da empresa)';

    saveCalcState();
  }
  [custoEl, margemEl].forEach(el => el.addEventListener('input', calcular));
  // A margem começa no padrão das configurações. Se a pessoa mudar aqui, vale só para este cálculo.
  let margemEditada = false;
  function margemDoCalculo() {
    const n = margemEl.value.trim() === '' ? config.margemPadrao : parseMoney(margemEl.value);
    return n > 0 && n < 80 ? n : config.margemPadrao;
  }
  margemEl.addEventListener('input', () => { margemEditada = margemEl.value.trim() !== ''; pintarDicaMargem(); });
  function pintarDicaMargem() {
    const igual = Math.abs(margemDoCalculo() - config.margemPadrao) < 1e-9;
    $('margem-padrao-dica').textContent = igual
      ? 'Margem padrão: ' + numTxt(config.margemPadrao) + '%. Mudar aqui vale só para este cálculo.'
      : 'Só para este cálculo. O padrão é ' + numTxt(config.margemPadrao) + '%.';
    $('margem-voltar-padrao').hidden = igual;
  }
  $('margem-voltar-padrao').addEventListener('click', () => {
    margemEl.value = numTxt(config.margemPadrao); margemEditada = false; calcular(); pintarDicaMargem();
  });
  function aoMudarConfig(margemAntes) {
    $('icms-dentro-txt').textContent = numTxt(config.icmsDentro) + '%';
    $('icms-fora-txt').textContent = numTxt(config.icmsFora) + '%';
    [['btn-dentro', 'Dentro de SC', config.icmsDentro], ['btn-fora', 'Fora de SC', config.icmsFora]].forEach(([id, nome, pct]) => {
      const sub = document.createElement('small');
      sub.className = 'tg-sub';
      sub.textContent = 'ICMS ' + numTxt(pct) + '%';
      $(id).textContent = nome;
      $(id).appendChild(sub);
    });
    if (!margemEditada || Math.abs(parseMoney(margemEl.value) - margemAntes) < 1e-9) {
      margemEl.value = numTxt(config.margemPadrao);
      margemEditada = false;
    }
    calcular();
    pintarDicaMargem();
    if (typeof aoMudarVendas === 'function') aoMudarVendas();
    if (typeof aoMudarConfigPmls === 'function') aoMudarConfigPmls();
  }

  // =====================================================
  // HISTÓRICO DE CÁLCULOS
  // =====================================================
  let calculos = [];


  async function salvarCalculoHistorico() {
    const custo = parseMoney(custoEl.value);
    if (!custo) { avisar('Informe o custo antes de salvar no histórico.'); return; }
    const aliquota = aliquotaDaOrigem(origem);
    const margemAuriverde = margemDoCalculo();
    const valorIcms = custo * (aliquota / 100);
    const preco = precoVendaDoItem({ custo, origem }, margemAuriverde);
    const registro = {
      produto: produtoEl.value.trim(), custo, origem, aliquota, valorIcms, margemAuriverde, preco,
      criadoPor: viewerId, criadoEm: Date.now(), data: todayISO()
    };
    gravar('set', 'calculos/' + novoId(), registro);
    const btn = $('btn-salvar-calculo');
    const original = btn.textContent;
    btn.textContent = 'Salvo ✓';
    setTimeout(() => { btn.textContent = original; }, 1500);
  }
  $('btn-salvar-calculo').addEventListener('click', salvarCalculoHistorico);

  $('btn-whatsapp').addEventListener('click', () => {
    const produto = produtoEl.value.trim();
    const precoTxt = $('out-preco').textContent;
    const custoTxt = fmt(parseMoney(custoEl.value));
    let msg = 'Preço calculado' + (produto ? (' — ' + produto) : '') + ':\n' +
      precoTxt + (veCustos() ? ' (custo ' + custoTxt + ', margem ' + numTxt(margemDoCalculo()) + '%, ' +
      (origem === 'dentro' ? 'dentro de SC' : 'fora de SC') + ')' : '');
    // Se o quadro do Claude bloquear a nova janela, copia o texto (ou mostra para copiar).
    const janela = window.open('https://wa.me/?text=' + encodeURIComponent(msg), '_blank');
    if (janela) { try { janela.opener = null; } catch (e) {} return; }
    const mostrar = () => avisar('Não consegui abrir o WhatsApp daqui. Copie o texto abaixo e cole na conversa:\n\n' + msg);
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(msg)
        .then(() => avisar('Não consegui abrir o WhatsApp daqui, mas o texto já foi copiado. É só colar na conversa.'))
        .catch(mostrar);
    } else {
      mostrar();
    }
  });

  function deleteCalculoHistorico(id) { gravar('delete', 'calculos/' + id); }

  let historicoRenderToken = 0;
  async function renderHistorico() {
    const token = ++historicoRenderToken;
    const container = $('historico-list');

    const ids = [...new Set(calculos.map(c => c.criadoPor).filter(Boolean))];
    let profileMap = {};
    try {
      const user = await claude.use('user');
      if (user && ids.length) profileMap = await user.profiles(ids);
    } catch (e) {}
    if (token !== historicoRenderToken) return; // chegou uma atualização mais nova

    container.innerHTML = '';
    $('historico-empty').hidden = calculos.length > 0;
    calculos.forEach(c => {
      const autor = c.criadoPor && profileMap[c.criadoPor] ? (profileMap[c.criadoPor].name || '') : '';
      const card = document.createElement('div');
      card.className = 'record';
      card.innerHTML = `
        <div class="record-top">
          <div>
            <span class="record-date"></span>
            <span class="hist-produto"></span>
          </div>
          <span class="record-x" title="Excluir">×</span>
        </div>
        <div class="hist-detail"></div>
        ${autor ? '<div class="record-autor"></div>' : ''}
      `;
      card.querySelector('.record-date').textContent = fmtDate(c.data);
      card.querySelector('.hist-produto').textContent = c.produto ? (' · ' + c.produto) : '';
      card.querySelector('.hist-detail').textContent = !veCustos() ? 'Preço ' + fmt(c.preco) :
        'Custo ' + fmt(c.custo) + ' → Preço ' + fmt(c.preco) + ' (margem ' + fmtPct(c.margemAuriverde) + ', ' +
        (c.origem === 'dentro' ? 'dentro de SC' : 'fora de SC') + ')';
      if (autor) card.querySelector('.record-autor').textContent = 'Salvo por ' + autor;
      card.querySelector('.record-x').hidden = !podeEditarRegistro('calc', c.criadoPor);
      card.querySelector('.record-x').addEventListener('click', () => {
        removerRegistro({ modulo: 'calc', caminho: 'calculos/' + c.id, criadoPor: c.criadoPor, rotulo: 'este cálculo do histórico' });
      });
      container.appendChild(card);
    });
  }

  // =====================================================
  // EXPORTAR EXCEL (.xlsx) — aba Cálculos + aba Visitas
  // =====================================================
  // A biblioteca (ExcelJS, ~1 MB) só é baixada quando alguém toca em Exportar.
  const EXCELJS_URL = 'https://cdn.jsdelivr.net/npm/exceljs@4.4.0/dist/exceljs.min.js';
  let excelJsPromise = null;
  function carregarExcelJS() {
    if (window.ExcelJS) return Promise.resolve(window.ExcelJS);
    if (!excelJsPromise) {
      excelJsPromise = new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = EXCELJS_URL;
        s.onload = () => (window.ExcelJS ? resolve(window.ExcelJS) : reject(new Error('ExcelJS não carregou')));
        s.onerror = () => { excelJsPromise = null; reject(new Error('Falha ao baixar ExcelJS')); };
        document.head.appendChild(s);
      });
    }
    return excelJsPromise;
  }

  // Gera um .xlsx no padrão do app: cabeçalho azul congelado, filtros,
  // larguras ajustadas, números de verdade e (opcional) linha de TOTAL.
  // abas: [{ nome, colunas: [{titulo, key, fmt, soma, wrap, max}], linhas: [{...}], total }]
  const XLSX_MOEDA = '"R$" #,##0.00';
  const XLSX_DATA = 'dd/mm/yyyy';
  async function gerarXlsx(ExcelJS, abas) {
    const VERDE = 'FF0E3B5C';
    const wb = new ExcelJS.Workbook();
    wb.creator = 'Ordenha360';
    wb.created = new Date();

    const paraData = iso => {
      if (!iso || typeof iso !== 'string') return null;
      const [y, m, d] = iso.split('-').map(Number);
      return new Date(Date.UTC(y, m - 1, d));
    };
    const txtLargura = (v, fmt) => {
      if (v == null || v === '') return '';
      if (v instanceof Date) return '00/00/0000';
      if (typeof v === 'number') return fmt === XLSX_MOEDA ? 'R$ ' + v.toFixed(2) + '000' : (Math.round(v * 10) / 10).toFixed(1) + '00';
      return String(v);
    };

    abas.forEach(({ nome, colunas, linhas, total }) => {
      const ws = wb.addWorksheet(nome, {
        views: [{ state: 'frozen', ySplit: 1 }],
        // impressão: paisagem, todas as colunas numa página de largura, cabeçalho repetido
        pageSetup: { orientation: 'landscape', paperSize: 9, fitToPage: true, fitToWidth: 1, fitToHeight: 0, printTitlesRow: '1:1' }
      });
      ws.columns = colunas.map(c => ({ header: c.titulo, key: c.key }));

      // datas chegam como 'AAAA-MM-DD' e viram datas de verdade no Excel
      const dados = linhas.map(l => colunas.map(c => {
        const v = l[c.key];
        if (v == null) return null;
        return (c.fmt === XLSX_DATA || c.ehData) ? paraData(v) : v;
      }));
      dados.forEach(vals => ws.addRow(vals));

      colunas.forEach((c, i) => {
        const col = ws.getColumn(i + 1);
        col.font = { name: 'IBM Plex Sans', size: 10 };
        if (c.fmt) col.numFmt = c.fmt;
        col.alignment = c.wrap ? { wrapText: true, vertical: 'top' } : { vertical: 'top' };
      });
      // células coloridas por faixa (ex.: Limp dentro / atenção / fora do padrão): linha.__cor = { chave: 'ok' | 'atencao' | 'fora' }
      const XLSX_FAIXA = { ok: ['FFE2F3F0', 'FF157A6E'], atencao: ['FFFBF0DA', 'FF9A6410'], fora: ['FFF6DED8', 'FFB5412B'] };
      linhas.forEach((l, ri) => {
        if (!l || !l.__cor) return;
        colunas.forEach((c, ci) => {
          const f = XLSX_FAIXA[l.__cor[c.key]];
          if (!f) return;
          const cell = ws.getRow(ri + 2).getCell(ci + 1);
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: f[0] } };
          cell.font = { name: 'IBM Plex Sans', size: 10, bold: true, color: { argb: f[1] } };
        });
      });

      const cab = ws.getRow(1);
      cab.height = 22;
      cab.eachCell(cell => {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: VERDE } };
        cell.font = { name: 'IBM Plex Sans', bold: true, color: { argb: 'FFFFFFFF' } }; cell.border = { bottom: { style: 'medium', color: { argb: 'FFF2B84B' } } };
        cell.alignment = { vertical: 'middle' };
      });

      const ultimaDados = linhas.length + 1;
      if (total) {
        const vals = colunas.map((c, i) => {
          if (i === 0) return 'TOTAL';
          if (!c.soma) return null;
          const letra = ws.getColumn(i + 1).letter;
          const soma = dados.reduce((s, row) => s + (Number(row[i]) || 0), 0);
          return linhas.length
            ? { formula: 'SUM(' + letra + '2:' + letra + ultimaDados + ')', result: Math.round(soma * 100) / 100 }
            : 0;
        });
        const tr = ws.addRow(vals);
        tr.eachCell({ includeEmpty: true }, (cell, n) => {
          cell.font = { name: 'IBM Plex Sans', bold: true };
          cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE2F3F0' } };
          cell.border = { top: { style: 'thin', color: { argb: VERDE } } };
          const c = colunas[n - 1];
          cell.numFmt = (c && c.fmt && c.fmt !== XLSX_DATA && !c.ehData) ? c.fmt : 'General';
        });
      }

      // filtro no cabeçalho (sem pegar a linha de TOTAL)
      ws.autoFilter = { from: { row: 1, column: 1 }, to: { row: Math.max(ultimaDados, 1), column: colunas.length } };

      // largura de cada coluna pelo maior conteúdo
      colunas.forEach((c, i) => {
        let max = c.titulo.length;
        dados.forEach(row => { max = Math.max(max, txtLargura(row[i], c.fmt).length); });
        ws.getColumn(i + 1).width = Math.min(c.max || 45, Math.max(10, max + 2));
      });
    });

    return wb.xlsx.writeBuffer();
  }

  // Planilha geral: aba Cálculos + aba Visitas
  function montarPlanilha(ExcelJS, calc, vis) {
    return gerarXlsx(ExcelJS, [
      {
        nome: 'Cálculos', total: true, linhas: calc,
        colunas: [
          { titulo: 'Data', key: 'data', fmt: XLSX_DATA },
          { titulo: 'Produto', key: 'produto' },
          { titulo: 'Origem', key: 'origem' },
          { titulo: 'Custo', key: 'custo', fmt: XLSX_MOEDA, soma: true },
          { titulo: 'ICMS', key: 'icms', fmt: XLSX_MOEDA, soma: true },
          { titulo: 'Margem (%)', key: 'margem', fmt: '0%' },
          { titulo: 'Preço de venda', key: 'preco', fmt: XLSX_MOEDA, soma: true },
          { titulo: 'Salvo por', key: 'salvoPor' }
        ].filter(c => veCustos() || !['custo', 'icms', 'margem'].includes(c.key))
      },
      {
        nome: 'Ordens de serviço', total: false, linhas: vis,
        colunas: [
          { titulo: 'Nº OS', key: 'numero' },
          { titulo: 'Data', key: 'data', fmt: XLSX_DATA },
          { titulo: 'Situação', key: 'situacao' },
          { titulo: 'Tipo', key: 'tipo' },
          { titulo: 'Produtor', key: 'produtor' },
          { titulo: 'Categoria', key: 'categoria' },
          { titulo: 'Defeito', key: 'defeito', wrap: true, max: 40 },
          { titulo: 'Itens revisados', key: 'itens', wrap: true, max: 40 },
          { titulo: 'Serviço feito', key: 'descricao', wrap: true, max: 50 },
          { titulo: 'Vácuo kPa', key: 'kpa', fmt: '0.#' },
          { titulo: 'Temp. leite (°C)', key: 'temp', fmt: '0.0' },
          { titulo: 'Próxima revisão', key: 'proxima', fmt: XLSX_DATA },
          { titulo: 'Total (R$)', key: 'total', fmt: XLSX_MOEDA },
          { titulo: 'Registrado por', key: 'registradoPor' }
        ]
      }
    ]);
  }

  // Planilha das médias de leite de todos os produtores
  function montarPlanilhaMedias(ExcelJS, linhas) {
    return gerarXlsx(ExcelJS, [{
      nome: 'Médias de leite', total: true, linhas,
      colunas: [
        { titulo: 'Produtor', key: 'produtor', max: 35 },
        { titulo: 'Litros/dia', key: 'mediaDia', fmt: '#,##0.0', soma: true },
        { titulo: 'L/vaca/dia', key: 'mediaVaca', fmt: '0.0' },
        { titulo: 'Vacas em lactação', key: 'vacas', fmt: '0', soma: true },
        { titulo: 'Período início', key: 'inicio', fmt: XLSX_DATA },
        { titulo: 'Período fim', key: 'fim', fmt: XLSX_DATA },
        { titulo: 'Último cálculo', key: 'dataCalculo', fmt: XLSX_DATA },
        { titulo: 'Variação', key: 'variacao', fmt: '+0.0%;-0.0%;0.0%' },
        { titulo: 'Salvo por', key: 'salvoPor' }
      ]
    }]);
  }

  // Cálculos antigos não guardavam o valor do ICMS: dá para recuperar como custo − custo líquido
  function icmsDoCalculo(c) {
    if (typeof c.valorIcms === 'number') return c.valorIcms;
    const divisor = (80 - (Number(c.margemAuriverde) || 17)) / 100;
    return (Number(c.custo) || 0) - (Number(c.preco) || 0) * divisor;
  }
  const r2 = n => Math.round((Number(n) || 0) * 100) / 100;

  async function coletarTodasVisitas() {
    if (!podeVer('visitas')) return [];
    const listas = await Promise.all(produtores.map(async p => {
      const vs = (await lerColecao('produtores/' + p.id + '/visitas')).filter(naoArquivado);
      return vs.map(v => ({ ...v, produtorNome: p.nome || '' }));
    }));
    return listas.flat();
  }

  async function exportarExcel() {
    const botoes = document.querySelectorAll('.exportar-excel');
    const originais = [...botoes].map(b => b.textContent);
    const ocupado = on => botoes.forEach((b, i) => { b.disabled = on; b.textContent = on ? 'Gerando planilha…' : originais[i]; });
    ocupado(true);
    try {
      const downloads = await claude.use('downloads');
      if (!downloads) { avisar('Exportar arquivos não está disponível aqui.'); return; }

      let todasVisitas;
      try { todasVisitas = await coletarTodasVisitas(); }
      catch (e) { avisar('Não consegui ler as visitas agora. Verifique a conexão e tente de novo.'); return; }
      if (!calculos.length && !todasVisitas.length) { avisar('Ainda não há cálculos nem visitas para exportar.'); return; }

      // nomes de quem salvou/registrou: resolvidos agora, nunca guardados no banco
      const ids = [...new Set([...calculos, ...todasVisitas].map(x => x.criadoPor).filter(Boolean))];
      let perfis = {};
      try {
        const user = await claude.use('user');
        if (user && ids.length) perfis = await user.profiles(ids);
      } catch (e) {}
      const nomeDe = id => (id && perfis[id] && perfis[id].name) || '';

      const calcRows = (podeVer('calc') ? calculos : []).slice()
        .sort((a, b) => (b.data || '').localeCompare(a.data || '') || (b.criadoEm || 0) - (a.criadoEm || 0))
        .map(c => ({
          data: c.data,
          produto: c.produto || '',
          origem: c.origem === 'dentro' ? 'Dentro de SC' : 'Fora de SC',
          custo: r2(c.custo),
          icms: r2(icmsDoCalculo(c)),
          margem: (Number(c.margemAuriverde) || 0) / 100,
          preco: r2(c.preco),
          salvoPor: nomeDe(c.criadoPor)
        }));
      const visRows = todasVisitas
        .sort((a, b) => (b.data || '').localeCompare(a.data || '') || a.produtorNome.localeCompare(b.produtorNome))
        .map(v => ({
          numero: v.numero ? numOS(v.numero) : '',
          data: v.data,
          situacao: OS_STATUS[statusOS(v)],
          tipo: OS_TIPOS[tipoOS(v)],
          defeito: v.defeito || '',
          total: Number(v.total) > 0 ? r2(v.total) : null,
          produtor: v.produtorNome,
          categoria: CAT_LABEL[v.categoria] || v.categoria || '',
          itens: temRevisao(v) ? itensFeitosLabels(v.revisao.itens).join(', ') : '',
          descricao: v.descricao || '',
          kpa: (v.vacuoKpa != null && v.vacuoKpa !== '') ? Number(v.vacuoKpa) : null,
          temp: temValor(v.temperaturaLeite) ? Number(v.temperaturaLeite) : null,
          proxima: temRevisao(v) && osConcluida(v) ? addMonthsISO(v.data, MESES_ATE_REVISAO) : null,
          registradoPor: nomeDe(v.criadoPor)
        }));

      let ExcelJS;
      try { ExcelJS = await carregarExcelJS(); }
      catch (e) { avisar('Não consegui carregar o gerador de planilhas. Verifique a internet e tente de novo.'); return; }

      const bytes = await montarPlanilha(ExcelJS, calcRows, visRows);
      const arquivo = new Blob([bytes], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      try {
        await downloads.save({ filename: nomeArquivoDemo('ordenha360-' + todayISO() + '.xlsx'), data: arquivo });
      } catch (e) {
        const code = e && e.code;
        if (code === 'declined') return; // a pessoa cancelou: tudo bem
        if (code === 'rate_limited') { avisar('Já tem um download aberto. Conclua ou feche ele e tente de novo.'); return; }
        if (['unavailable', 'not_granted', 'capability_disabled', 'capability_removed', 'extension_not_enabled'].includes(code)) {
          avisar('Exportar arquivos não está disponível aqui.');
          return;
        }
        avisar('Não foi possível salvar a planilha' + (e && e.message ? ': ' + e.message : '.'));
      }
    } finally {
      ocupado(false);
    }
  }
  document.querySelectorAll('.exportar-excel').forEach(b => b.addEventListener('click', exportarExcel));

  // =====================================================
  // VISITAS: PRODUTORES
  // =====================================================
  const CAT_COLOR = { ordenha: 'var(--ordenha)', resfriador: 'var(--resfriador)', conforto: 'var(--conforto)' };
  const CAT_LABEL = { ordenha: 'Ordenha', resfriador: 'Resfriador', conforto: 'Conforto animal' };

  // Busca sem diferenciar maiúsculas nem acentos ("joao" acha "João")
  function normalizarBusca(s) {
    return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  }

  let produtores = [];
  let currentProdutorId = null;
  let visitas = [];
  let unsubVisitas = null;


  // ---------- cadastro do produtor: textos e links ----------
  const UFS = ['AC', 'AL', 'AP', 'AM', 'BA', 'CE', 'DF', 'ES', 'GO', 'MA', 'MT', 'MS', 'MG', 'PA', 'PB', 'PR',
    'PE', 'PI', 'RJ', 'RN', 'RS', 'RO', 'RR', 'SC', 'SP', 'SE', 'TO'];
  // "Linha São José · Chapecó" (o que aparece embaixo do nome em todas as listas)
  function localDoProdutor(p) {
    return [p && p.linha, p && p.cidade].filter(Boolean).join(' · ');
  }
  // texto buscável: nome, propriedade, linha e cidade
  function textoBuscaProdutor(p) {
    return normalizarBusca([p.nome, p.propriedade, p.linha, p.cidade, p.matricula, p.codFornecedor].filter(Boolean).join(' '));
  }
  // Lê coordenadas coladas ("-27.1, -52.6") ou dentro de um link do Google Maps (…@-27.1,-52.6… ou ?q=-27.1,-52.6)
  function lerLocalizacao(texto) {
    const s = String(texto || '').trim();
    const m = s.match(/(-?\d{1,2}\.\d{3,})\s*,\s*(-?\d{1,3}\.\d{3,})/);
    if (m) {
      const lat = parseFloat(m[1]), lng = parseFloat(m[2]);
      if (Math.abs(lat) <= 90 && Math.abs(lng) <= 180) return { lat, lng };
    }
    return { lat: null, lng: null };
  }
  function ehLinkSeguro(s) { return /^https:\/\/[^\s]+$/i.test(String(s || '').trim()); }
  function linksMapa(p) {
    if (!p) return null;
    if (p.lat != null && p.lng != null) {
      return {
        google: 'https://www.google.com/maps/dir/?api=1&destination=' + p.lat + ',' + p.lng,
        apple: 'https://maps.apple.com/?daddr=' + p.lat + ',' + p.lng
      };
    }
    if (ehLinkSeguro(p.localizacao)) return { google: p.localizacao.trim(), apple: null };
    const endereco = [p.linha, p.cidade, p.estado].filter(Boolean).join(', ');
    if (p.cidade) {
      const q = encodeURIComponent(endereco);
      return { google: 'https://www.google.com/maps/dir/?api=1&destination=' + q, apple: 'https://maps.apple.com/?daddr=' + q };
    }
    return null;
  }
  function linkWhatsApp(tel) {
    let d = String(tel || '').replace(/\D/g, '').replace(/^0+/, '');
    if (!d) return null;
    if (d.length === 10 || d.length === 11) d = '55' + d;
    return 'https://wa.me/' + d;
  }

  // mantém as opções dos filtros de cidade/linha (e as sugestões do cadastro) em dia
  function atualizarOpcoesLocal() {
    const cidades = [...new Set(produtores.map(p => (p.cidade || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b));
    const selCidade = $('filtro-cidade').value;
    const linhasDe = produtores.filter(p => !selCidade || (p.cidade || '').trim() === selCidade);
    const linhas = [...new Set(linhasDe.map(p => (p.linha || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b));
    // só refaz a lista quando as opções mudaram (refazer à toa fecha a lista no iPhone no meio da escolha)
    const preencher = (sel, rotulo, valores) => {
      const atual = sel.value;
      const assinatura = valores.join('\u0001');
      if (sel.dataset.opcoes === assinatura) return;
      sel.dataset.opcoes = assinatura;
      sel.innerHTML = '';
      const o0 = document.createElement('option'); o0.value = ''; o0.textContent = rotulo; sel.appendChild(o0);
      valores.forEach(v => { const o = document.createElement('option'); o.value = v; o.textContent = v; sel.appendChild(o); });
      sel.value = valores.includes(atual) ? atual : '';
    };
    preencher($('filtro-cidade'), 'Todas as cidades', cidades);
    preencher($('filtro-linha'), 'Todas as linhas', linhas);
    const dl = (id, valores) => {
      const el = $(id);
      const assinatura = valores.join('\u0001');
      if (el.dataset.opcoes === assinatura) return;
      el.dataset.opcoes = assinatura;
      el.innerHTML = '';
      valores.forEach(v => { const o = document.createElement('option'); o.value = v; el.appendChild(o); });
    };
    dl('lista-cidades', cidades);
    dl('lista-linhas', [...new Set(produtores.map(p => (p.linha || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b)));
  }

  function renderProdutoresList() {
    const container = $('produtor-list');
    container.innerHTML = '';
    atualizarOpcoesLocal();
    const termo = normalizarBusca($('produtor-busca').value.trim());
    const cidade = $('filtro-cidade').value;
    const linha = $('filtro-linha').value;
    const lista = produtores
      .filter(p => !termo || textoBuscaProdutor(p).includes(termo))
      .filter(p => !cidade || (p.cidade || '').trim() === cidade)
      .filter(p => !linha || (p.linha || '').trim() === linha)
      .filter(passaFiltrosCadastro)
      .sort((a, b) => (a.nome || '').localeCompare(b.nome || ''));
    preencherFiltroTecnico();
    opcaoArquivados();
    $('produtor-contagem').textContent = lista.length === produtores.length
      ? produtores.length + (produtores.length === 1 ? ' produtor' : ' produtores')
      : lista.length + ' de ' + produtores.length + ' produtores';

    const soArquivados = produtores.length === 0 && nivel('produtores') >= 3 && produtoresTodos.some(p => p.arquivado);
    $('produtor-busca-wrap').hidden = produtores.length === 0 && !soArquivados;
    $('produtor-empty').hidden = lista.length > 0;
    $('produtor-empty').textContent = soArquivados
      ? 'Nenhum produtor ativo na lista. Os arquivados aparecem em Situação → Arquivados.'
      : produtores.length === 0
      ? 'Nenhum produtor cadastrado ainda. Toque no + para adicionar o primeiro' + (ehAdmin() ? ' ou importe uma planilha.' : '.')
      : 'Nenhum produtor encontrado com essa busca.';

    lista.forEach(p => {
      const card = document.createElement('div');
      card.className = 'produtor-card';
      card.innerHTML = '<div class="produtor-name"></div><div class="produtor-local" hidden></div><div class="produtor-meta"></div><div class="proxima" hidden></div><div class="selos-produtor" hidden></div>';
      pintarSelos(card.querySelector('.selos-produtor'), p, p.proximaRevisao ? ['selo-vencida'] : []);
      card.querySelector('.produtor-name').textContent = p.nome;
      if (localDoProdutor(p)) {
        card.querySelector('.produtor-local').textContent = localDoProdutor(p);
        card.querySelector('.produtor-local').hidden = false;
      }
      card.querySelector('.produtor-meta').textContent = p.ultimaVisitaData
        ? ('Última visita: ' + fmtDate(p.ultimaVisitaData) + ' · ' + (CAT_LABEL[p.ultimaVisitaCategoria] || ''))
        : 'Nenhuma visita registrada ainda';
      if (p.proximaRevisao) {
        const st = proximaStatus(p.proximaRevisao);
        const el = card.querySelector('.proxima');
        el.textContent = st.txt;
        el.className = 'proxima ' + st.cls;
        el.hidden = false;
      }
      const rt = document.createElement('button');
      rt.type = 'button';
      rt.className = 'rota-toggle' + (naRota(p.id) ? ' on' : '');
      rt.dataset.pid = p.id;
      rt.textContent = naRota(p.id) ? '✓ Na rota' : '📍 Rota';
      rt.setAttribute('aria-pressed', naRota(p.id) ? 'true' : 'false');
      rt.setAttribute('aria-label', (naRota(p.id) ? 'Tirar ' : 'Colocar ') + (p.nome || '') + (naRota(p.id) ? ' da rota do dia' : ' na rota do dia'));
      rt.addEventListener('click', (e) => { e.stopPropagation(); alternarRota(p.id); });
      card.appendChild(rt);
      card.addEventListener('click', () => openProdutor(p.id));
      container.appendChild(card);
    });
    aoMudarRota();
    renderPainelRevisoes();
    // dados de produtor mudaram (aqui ou em outro aparelho): atualiza as telas de leite abertas
    if (!$('view-leite').hidden) calcularLeite();
    if (!$('view-medias').hidden) renderMediasTabela();
    if (currentProdutorId) { renderProdutorLeite(); renderProdutorContato(); renderProdutorCompras(); }
    if (!$('view-vendas').hidden) renderResumoVendas();
    aoMudarProdutoresPmls();
  }
  $('produtor-busca').addEventListener('input', renderProdutoresList);
  $('filtro-cidade').addEventListener('change', () => { $('filtro-linha').value = ''; renderProdutoresList(); });
  $('filtro-linha').addEventListener('change', renderProdutoresList);

  // Painel da tela inicial: todas as próximas revisões, da mais urgente para a mais distante.
  // Atrasadas em vermelho, próximos 15 dias em amarelo, as demais neutras.
  // Sem nenhuma revisão agendada, o painel some.
  // No setor mostra só as 5 primeiras (a data mais antiga vem antes, então as vencidas ficam no topo);
  // "Ver todas" abre a lista inteira ali mesmo.
  var revisoesTodas = false;
  function renderPainelRevisoes() {
    const container = $('painel-revisoes-list');
    container.innerHTML = '';
    const agendadas = produtores
      .filter(p => p.proximaRevisao)
      .sort((a, b) => a.proximaRevisao.localeCompare(b.proximaRevisao));

    $('painel-revisoes').hidden = agendadas.length === 0;
    const mais = $('painel-revisoes-mais');
    mais.hidden = agendadas.length <= 5;
    mais.textContent = revisoesTodas ? 'Ver só as 5 primeiras' : 'Ver todas (' + agendadas.length + ')';

    (revisoesTodas ? agendadas : agendadas.slice(0, 5)).forEach(p => {
      const st = proximaStatus(p.proximaRevisao);
      const item = document.createElement('div');
      item.className = 'painel-item ' + st.cls;
      item.innerHTML = '<div class="painel-nome"></div><div class="painel-quando"></div>';
      item.querySelector('.painel-nome').textContent = p.nome;
      item.querySelector('.painel-quando').textContent = st.txt;
      item.addEventListener('click', () => openProdutor(p.id, { aba: 'visitas', voltar: 'setor' }));
      container.appendChild(item);
    });
  }
  $('painel-revisoes-mais').addEventListener('click', () => { revisoesTodas = !revisoesTodas; renderPainelRevisoes(); });

  // Devolve (Promise) o id do produtor criado, ou null se não conseguiu.
  // Aceita só o nome (texto) ou o cadastro completo (objeto).
  function addProdutor(dados) {
    const cadastro = typeof dados === 'string' ? { nome: dados } : dados;
    if (!podeLancar('produtores')) { avisar('Você não tem permissão para cadastrar produtores.'); return Promise.resolve(null); }
    const doc = { infoOrdenha: '', infoResfriador: '', infoVacas: '', estado: 'SC', ...cadastro, criadoPor: viewerId || null, criadoEm: Date.now() };
    const id = novoId();
    gravar('set', 'produtores/' + id, doc);
    registrarAtividade('criou', 'produtor', id, doc.nome);
    return Promise.resolve(id);
  }
  function updateProdutor(id, fields) { return gravar('update', 'produtores/' + id, fields); }
  function deleteProdutorById(id) { return gravar('delete', 'produtores/' + id); }

  function subscribeVisitas(pid) {
    if (unsubVisitas) { unsubVisitas(); unsubVisitas = null; }
    visitasBrutas = []; visitasConfiavel = false;
    unsubVisitas = assinar('produtores/' + pid + '/visitas', (lista, confiavel) => {
      if (currentProdutorId !== pid) return;
      visitasBrutas = lista;
      visitas = lista.filter(naoArquivado);
      if (confiavel) visitasConfiavel = true;
      renderVisitas();
      // só recalcula "última visita" com a lista de verdade (não com a cópia antiga do aparelho)
      if (confiavel) { syncUltimaVisita(pid); repararIndiceOS(pid); }
    }, (a, b) => (b.data || '').localeCompare(a.data || '') || (b.criadoEm || 0) - (a.criadoEm || 0));
  }
  // Recalcula "última visita" e "próxima revisão" a partir da lista real de visitas
  // e guarda no produtor (é isso que alimenta a lista e o painel da tela inicial).
  // Só grava se algo mudou, pra não escrever no banco toda vez que a página abre.
  function syncUltimaVisita(pid) {
    const mais = visitas.filter(osConcluida).sort((a, b) => (b.data || '').localeCompare(a.data || ''))[0] || null;
    const ultimaRev = ultimaRevisaoDe(visitas);
    const campos = {
      ultimaVisitaData: mais ? mais.data : null,
      ultimaVisitaCategoria: mais ? mais.categoria : null,
      proximaRevisao: ultimaRev ? addMonthsISO(ultimaRev.data, MESES_ATE_REVISAO) : null
    };
    const temp = ultimaTemperatura(visitas);
    campos.ultimaTempLeite = temp ? temp.valor : null;
    campos.ultimaTempLeiteData = temp ? temp.data : null;
    // próxima troca de componente do plano preventivo (o servidor usa no aviso ao celular do produtor)
    try {
      const pl = planoDoProdutor(produtores.find(x => x.id === pid), visitas);
      const prox = pl.itens.filter(i => i.proxima).sort((a, b) => a.proxima.localeCompare(b.proxima))[0];
      campos.proximaTrocaData = prox ? prox.proxima : null;
      campos.proximaTrocaComp = prox ? prox.comp.nome : null;
    } catch (e) {}
    const p = produtores.find(x => x.id === pid);
    if (p && Object.keys(campos).every(k => (p[k] ?? null) === campos[k])) return;
    updateProdutor(pid, campos);
  }
  function addVisita(pid, data, id) {
    return gravar('set', 'produtores/' + pid + '/visitas/' + (id || novoId()), { ...data, criadoPor: data.criadoPor || viewerId || null, criadoEm: Date.now() });
  }
  function updateVisita(pid, vid, data) {
    return gravar('update', 'produtores/' + pid + '/visitas/' + vid, { ...data, atualizadoPor: viewerId || null, atualizadoEm: Date.now() });
  }
  function deleteVisita(pid, vid) {
    // as fotos da visita vão junto
    const v = visitas.find(x => x.id === vid);
    if (v && v.estoqueBaixa) estoqueAposGravarOS(pid, vid, v, true); // as peças baixadas voltam ao estoque
    ((v && v.fotos) || []).forEach(f => { if (f && f.id) gravar('delete', 'produtores/' + pid + '/fotos/' + f.id); });
    gravar('delete', 'ordens/' + vid);
    return gravar('delete', 'produtores/' + pid + '/visitas/' + vid);
  }

  function closeProdutorDetail() {
    if (unsubVisitas) { unsubVisitas(); unsubVisitas = null; }
    desligarEquipamentos();
    desligarNutricao();
    desligarLotes();
    desligarColetas();
    desligarPlano();
    desligarVeterinaria();
    desligarAnimais();
    if (ppId) desligarFichaPmls();
    currentProdutorId = null;
  }

  // A lista da aba Manutenção (ordens de serviço) é desenhada por renderOSFicha(), no bloco MANUTENÇÃO.
  function renderVisitas() { renderOSFicha(); }

  // =====================================================
  // GOOGLE AGENDA — "Adicionar à agenda" na revisão mais recente do produtor
  // =====================================================
  // Usa o conector Google Calendar de QUEM ESTÁ USANDO o app: cada pessoa
  // adiciona na própria agenda. Sem o conector, o botão não aparece.
  const AGENDA_SERVER = 'Google Calendar';
  let agendaDisponivel = false;
  const agendadoNestaSessao = new Set();

  async function initAgenda() {
    try {
      if (typeof claude === 'undefined' || !claude || !claude.use) throw new Error('fora do Claude');
      const mcp = await claude.use('mcp');
      if (!mcp) return;
      const res = await mcp.listTools(AGENDA_SERVER);
      const srv = ((res && res.servers) || []).find(x => x.server === AGENDA_SERVER);
      agendaDisponivel = !!srv && (srv.tools || []).some(t => t.name === 'create_event');
    } catch (e) {
      agendaDisponivel = false;
    }
    if (currentProdutorId) renderVisitas();
    try { if (!$('view-ordens').hidden) renderAgendaSemana(osVisiveis()); } catch (e) {}
  }

  function addDaysISO(iso, n) {
    const [y, m, d] = iso.split('-').map(Number);
    const dt = new Date(y, m - 1, d + n);
    return dt.getFullYear() + '-' + String(dt.getMonth() + 1).padStart(2, '0') + '-' + String(dt.getDate()).padStart(2, '0');
  }
  // "2027-03-24" → "2027-03-24T00:00:00-03:00" (meia-noite no fuso de quem está usando)
  function meiaNoiteLocal(iso) {
    const [y, m, d] = iso.split('-').map(Number);
    const off = -new Date(y, m - 1, d).getTimezoneOffset();
    const a = Math.abs(off);
    return iso + 'T00:00:00' + (off >= 0 ? '+' : '-') +
      String(Math.floor(a / 60)).padStart(2, '0') + ':' + String(a % 60).padStart(2, '0');
  }
  function jaAgendado(v, proxima) {
    if (viewerId && v.agendadoPor && v.agendadoPor[viewerId] === proxima) return true;
    return agendadoNestaSessao.has(v.id + '|' + proxima);
  }
  function resumoParaAgenda(v, nome) {
    const linhas = ['Última revisão da ordenhadeira de ' + nome + ' em ' + fmtDate(v.data) + '.'];
    const feitos = itensFeitosLabels(v.revisao.itens);
    if (feitos.length) linhas.push('Itens revisados: ' + feitos.join(', ') + '.');
    if (v.vacuoKpa) linhas.push('Vácuo deixado: ' + v.vacuoKpa + ' kPa.');
    if (v.descricao) linhas.push('Observações: ' + v.descricao);
    if (v.revisao.responsavelTecnico) linhas.push('Responsável técnico: ' + v.revisao.responsavelTecnico + '.');
    linhas.push('', 'Criado pelo app Ordenha360.');
    return linhas.join('\n');
  }

  async function adicionarAgenda(v, btn) {
    const pid = currentProdutorId;
    const p = produtores.find(x => x.id === pid);
    const nome = p ? p.nome : '';
    const proxima = addMonthsISO(v.data, MESES_ATE_REVISAO);
    btn.disabled = true;
    btn.textContent = 'Adicionando…';
    try {
      const mcp = await claude.use('mcp');
      if (!mcp) throw { code: 'capability_disabled' };
      await mcp.callTool(AGENDA_SERVER, 'create_event', {
        summary: 'Revisão de ordenhadeira – ' + nome,
        allDay: true,
        startTime: meiaNoiteLocal(proxima),
        endTime: meiaNoiteLocal(addDaysISO(proxima, 1)),
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/Sao_Paulo',
        description: resumoParaAgenda(v, nome),
        overrideReminders: [{ method: 'popup', minutes: 900 }] // na véspera, às 9h
      });
    } catch (e) {
      tratarErroAgenda(e, btn);
      return;
    }
    agendadoNestaSessao.add(v.id + '|' + proxima);
    btn.textContent = 'Adicionado à agenda ✓';
    btn.classList.add('done');
    // lembra que ESTA pessoa já adicionou (guarda só o id dela, nunca o nome)
    if (viewerId && pid) {
      gravar('update', 'produtores/' + pid + '/visitas/' + v.id, { agendadoPor: { [viewerId]: proxima } });
    }
  }

  function tratarErroAgenda(e, btn) {
    const code = e && e.code;
    const restaurar = () => { btn.disabled = false; btn.textContent = '📅 Adicionar à agenda'; };
    const esconder = () => { agendaDisponivel = false; if (currentProdutorId) renderVisitas(); };
    switch (code) {
      case 'server_not_connected':
        esconder();
        avisar('O Google Agenda não está conectado na sua conta. Para usar este botão, conecte em claude.ai → Configurações → Conectores.');
        break;
      case 'needs_reauth':
        restaurar();
        avisar('A conexão com o Google Agenda expirou. Reconecte em claude.ai → Configurações → Conectores e tente de novo.');
        break;
      case 'selection_required':
        restaurar();
        avisar('Você tem mais de uma conta do Google Agenda conectada. Escolha qual usar e tente de novo.');
        break;
      case 'not_in_manifest':
        esconder();
        avisar('O acesso ao Google Agenda não foi permitido para este app.');
        break;
      case 'blocked_by_policy':
      case 'approval_required':
      case 'not_granted':
      case 'capability_disabled':
      case 'capability_removed':
        esconder();
        avisar('O Google Agenda não está disponível para este app aqui.');
        break;
      case 'tool_error':
        restaurar();
        avisar('O Google Agenda recusou o evento' + (e.message ? ': ' + e.message : '.'));
        break;
      default:
        // sem resposta clara: o evento PODE ter sido criado, então não repete sozinho
        restaurar();
        avisar('Não deu para confirmar se o evento foi criado. Confira sua agenda antes de tentar de novo, para não duplicar.');
    }
  }

  // =====================================================
  // AGENDA DO CELULAR — arquivo de evento .ics (iPhone e Android)
  // =====================================================
  // Sem o conector do Google Agenda (ou fora do Claude), o botão gera um arquivo
  // .ics que a agenda do próprio celular abre: título, data, local, descrição e
  // lembrete na véspera. Com o conector, o mesmo botão cria o evento no Google Agenda.
  function horaLocalISO(iso, hhmm) {
    const [y, m, d] = iso.split('-').map(Number);
    const [h, mi] = hhmm.split(':').map(Number);
    const off = -new Date(y, m - 1, d, h, mi).getTimezoneOffset();
    const a = Math.abs(off);
    return iso + 'T' + String(h).padStart(2, '0') + ':' + String(mi).padStart(2, '0') + ':00' + (off >= 0 ? '+' : '-') +
      String(Math.floor(a / 60)).padStart(2, '0') + ':' + String(a % 60).padStart(2, '0');
  }
  function somarHora(hhmm, min) {
    const [h, m] = hhmm.split(':').map(Number);
    const t = Math.min(h * 60 + m + min, 23 * 60 + 59);
    return String(Math.floor(t / 60)).padStart(2, '0') + ':' + String(t % 60).padStart(2, '0');
  }
  const horaValida = h => typeof h === 'string' && /^\d{2}:\d{2}$/.test(h);
  function localAgenda(p) {
    if (!p) return '';
    return [p.propriedade, p.linha, p.cidade ? p.cidade + (p.estado ? ' - ' + p.estado : '') : ''].filter(Boolean).join(', ');
  }
  function icsTxt(v) { return String(v == null ? '' : v).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n'); }
  // linhas de no máximo 75 bytes (regra do formato), continuando com um espaço
  function icsDobrar(linha) {
    const enc = new TextEncoder();
    const out = [];
    let atual = '', bytes = 0;
    for (const ch of linha) {
      const b = enc.encode(ch).length;
      if (bytes + b > 75) { out.push(atual); atual = ' '; bytes = 1; }
      atual += ch; bytes += b;
    }
    out.push(atual);
    return out.join('\r\n');
  }
  function gerarIcs(ev) {
    const d = iso => iso.replace(/-/g, '');
    const dh = (iso, h) => d(iso) + 'T' + h.replace(':', '') + '00';
    const stamp = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
    const L = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Ordenha360//App Ordenha360//PT-BR', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', 'BEGIN:VEVENT',
      'UID:' + String(ev.uid || novoId()).replace(/[^\w.-]/g, '') + '@auriverde.app', 'DTSTAMP:' + stamp];
    if (horaValida(ev.hora)) {
      L.push('DTSTART:' + dh(ev.data, ev.hora), 'DTEND:' + dh(ev.data, horaValida(ev.horaFim) ? ev.horaFim : somarHora(ev.hora, 60)));
    } else {
      L.push('DTSTART;VALUE=DATE:' + d(ev.data), 'DTEND;VALUE=DATE:' + d(addDaysISO(ev.data, 1)));
    }
    L.push('SUMMARY:' + icsTxt(ev.titulo));
    if (ev.local) L.push('LOCATION:' + icsTxt(ev.local));
    if (ev.descricao) L.push('DESCRIPTION:' + icsTxt(ev.descricao));
    // lembrete 1 dia antes (evento de dia inteiro: na véspera, às 9h)
    L.push('BEGIN:VALARM', 'ACTION:DISPLAY', 'DESCRIPTION:' + icsTxt(ev.titulo), 'TRIGGER:' + (horaValida(ev.hora) ? '-P1D' : '-PT15H'), 'END:VALARM');
    L.push('END:VEVENT', 'END:VCALENDAR');
    return L.map(icsDobrar).join('\r\n') + '\r\n';
  }
  function nomeArqIcs(t) {
    return (String(t || 'evento').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '').toLowerCase().slice(0, 60) || 'evento');
  }
  async function salvarIcs(ev, btn) {
    const txt = gerarIcs(ev);
    const nome = nomeArquivoDemo(nomeArqIcs(ev.titulo) + '.ics');
    const blob = new Blob([txt], { type: 'text/calendar;charset=utf-8' });
    const feito = () => { if (btn) { btn.textContent = '📅 Agenda do celular ✓'; btn.classList.add('done'); } };
    // dentro do Claude: o arquivo sai pelo download do app
    const downloads = null; // versão do GitHub: sempre pelo navegador
    if (downloads) {
      try {
        await downloads.save({ filename: nome, data: blob });
        feito();
        avisar('Evento salvo no arquivo ' + nome + '. Abra o arquivo no celular e toque em "Adicionar" para colocar na agenda (com lembrete na véspera).');
        return;
      } catch (e) {
        const code = e && e.code;
        if (code === 'declined') return;
        if (code === 'rate_limited') { avisar('Já tem um download aberto. Conclua ou feche ele e tente de novo.'); return; }
        // sem o download do Claude: segue pelo navegador
      }
    }
    // fora do Claude: o iPhone abre o .ics direto na agenda; o Android baixa e abre na agenda
    try {
      const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
      if (ios) {
        window.location.href = 'data:text/calendar;charset=utf-8,' + encodeURIComponent(txt);
      } else {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = nome; a.rel = 'noopener';
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 60000);
      }
      feito();
    } catch (e) {
      avisar('Não consegui gerar o arquivo da agenda neste aparelho.');
    }
  }
  async function adicionarGoogleEvento(ev, btn) {
    btn.disabled = true;
    btn.textContent = 'Adicionando…';
    try {
      const mcp = await claude.use('mcp');
      if (!mcp) throw { code: 'capability_disabled' };
      const args = {
        summary: ev.titulo,
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/Sao_Paulo',
        description: ev.descricao || '',
        overrideReminders: [{ method: 'popup', minutes: horaValida(ev.hora) ? 1440 : 900 }]
      };
      if (ev.local) args.location = ev.local;
      if (horaValida(ev.hora)) {
        args.startTime = horaLocalISO(ev.data, ev.hora);
        args.endTime = horaLocalISO(ev.data, horaValida(ev.horaFim) ? ev.horaFim : somarHora(ev.hora, 60));
      } else {
        args.allDay = true;
        args.startTime = meiaNoiteLocal(ev.data);
        args.endTime = meiaNoiteLocal(addDaysISO(ev.data, 1));
      }
      await mcp.callTool(AGENDA_SERVER, 'create_event', args);
    } catch (e) {
      tratarErroAgenda(e, btn);
      return;
    }
    btn.textContent = 'Adicionado à agenda ✓';
    btn.classList.add('done');
  }
  // um botão só: Google Agenda quando o conector existe; senão, a agenda do celular (.ics)
  function botaoAgenda(ev, rotulo) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'agenda-btn';
    if (agendaDisponivel) {
      b.textContent = rotulo || '📅 Adicionar ao Google Agenda';
      b.addEventListener('click', e => { e.stopPropagation(); adicionarGoogleEvento(ev, b); });
    } else {
      b.textContent = rotulo || '📅 Adicionar à agenda do celular';
      b.addEventListener('click', e => { e.stopPropagation(); salvarIcs(ev, b); });
    }
    return b;
  }
  function eventoDaOS(o, p) {
    const nome = (p && p.nome) || o.produtorNome || 'Produtor';
    const tec = o.tecnicoId ? nomeReal(o.tecnicoId) : '';
    const linhas = [
      numOS(o.numero) + ' · ' + [OS_TIPOS[tipoOS(o)], CAT_LABEL[o.categoria]].filter(Boolean).join(' · '),
      o.motivo ? 'Motivo: ' + o.motivo : '',
      tec ? 'Técnico: ' + tec : '',
      p && p.telefone ? 'Telefone do produtor: ' + p.telefone : '',
      p && p.referencia ? 'Referência: ' + p.referencia : ''
    ].filter(Boolean);
    return {
      uid: 'os-' + o.id + '-' + o.agendadaPara,
      titulo: (CAT_LABEL[o.categoria] || 'OS') + ' – ' + nome + ' (' + numOS(o.numero) + ')',
      data: o.agendadaPara, ...turnoDoEvento(o),
      local: localAgenda(p) || o.produtorLocal || '',
      descricao: linhas.join('\n') + '\n\nCriado pelo app Ordenha360.'
    };
  }
  function eventoPreventiva(p, itens) {
    const data = itens[0].proxima;
    return {
      uid: 'prev-' + p.id + '-' + data,
      titulo: 'Troca preventiva – ' + (p.nome || '') + ': ' + itens.map(i => i.comp.nome).join(', '),
      data, local: localAgenda(p),
      descricao: ['Próxima troca prevista pelo plano preventivo:'].concat(itens.map(i => '• ' + i.comp.nome + ' (' + vidaTxt(i.comp) + (i.ultima ? '; última troca em ' + fmtDate(i.ultima.data) : '') + ')'))
        .concat(['', 'Criado pelo app Ordenha360.']).join('\n')
    };
  }
  function linhaBotaoAgenda(ev, rotulo) {
    const d = document.createElement('div');
    d.className = 'agenda-linha';
    d.appendChild(botaoAgenda(ev, rotulo));
    return d;
  }

  // ---------- cadastro do produtor (o mesmo em Vendas, Visitas e Média de leite) ----------
  // Quem abre para cadastrar pode receber o produtor criado (ex.: já seleciona ele).
  let aoCriarProdutor = null;
  let editandoProdutorId = null;
  (function preencherUFs() {
    UFS.forEach(uf => { const o = document.createElement('option'); o.value = uf; o.textContent = uf; $('produtor-estado-input').appendChild(o); });
  })();
  function preencherFormProdutor(p) {
    $('produtor-nome-input').value = p.nome || '';
    $('produtor-propriedade-input').value = p.propriedade || '';
    $('produtor-telefone-input').value = p.telefone || '';
    $('produtor-linha-input').value = p.linha || '';
    $('produtor-cidade-input').value = p.cidade || '';
    $('produtor-estado-input').value = UFS.includes(p.estado) ? p.estado : 'SC';
    $('produtor-referencia-input').value = p.referencia || '';
    $('produtor-altitude-input').value = temValor(p.altitude) ? String(Math.round(Number(p.altitude))) : '';
    $('produtor-local-input').value = p.localizacao || (p.lat != null ? p.lat + ', ' + p.lng : '');
    mostrarDicaLocal();
    preencherCamposNovos(p);
  }
  function mostrarDicaLocal() {
    const txt = $('produtor-local-input').value.trim();
    const dica = $('produtor-local-dica');
    const loc = lerLocalizacao(txt);
    if (loc.lat != null) {
      dica.textContent = '📍 Posição reconhecida: ' + loc.lat.toFixed(5).replace('.', ',') + ' / ' + loc.lng.toFixed(5).replace('.', ',');
      dica.className = 'campo-dica ok';
    } else if (ehLinkSeguro(txt)) {
      dica.textContent = '🔗 Link do mapa salvo. "Abrir no mapa" vai usar este link.';
      dica.className = 'campo-dica ok';
    } else {
      dica.textContent = 'Na propriedade, abra o Google Maps, toque no ponto azul e copie as coordenadas (ou toque em Compartilhar e copie o link). Depois cole aqui.';
      dica.className = 'campo-dica';
    }
  }
  $('produtor-local-input').addEventListener('input', mostrarDicaLocal);
  function lerFormProdutor() {
    const localizacao = $('produtor-local-input').value.trim();
    const loc = lerLocalizacao(localizacao);
    // altitude da propriedade (m): entra no fator de altitude da vazão da bomba pelo manual
    const altTxt = $('produtor-altitude-input').value.trim();
    const altN = altTxt ? Math.round(parseMoney(altTxt)) : null;
    return {
      altitude: altN != null && altN >= 0 ? altN : null,
      nome: $('produtor-nome-input').value.trim(),
      propriedade: $('produtor-propriedade-input').value.trim(),
      telefone: $('produtor-telefone-input').value.trim(),
      linha: $('produtor-linha-input').value.trim(),
      cidade: $('produtor-cidade-input').value.trim(),
      estado: $('produtor-estado-input').value || 'SC',
      referencia: $('produtor-referencia-input').value.trim(),
      localizacao, lat: loc.lat, lng: loc.lng,
      ...lerCamposNovos()
    };
  }
  function abrirNovoProdutor(nomeInicial = '', callback = null) {
    aoCriarProdutor = callback;
    editandoProdutorId = null;
    $('modal-produtor-titulo').textContent = 'Novo produtor';
    preencherFormProdutor({ nome: nomeInicial, estado: 'SC' });
    $('modal-produtor').hidden = false;
    // leva o cursor ao nome, a não ser que a pessoa já tenha tocado em outro campo
    setTimeout(() => {
      const ativo = document.activeElement;
      if (!ativo || ativo === document.body || !$('modal-produtor').contains(ativo)) $('produtor-nome-input').focus();
    }, 50);
  }
  function abrirEditarProdutor(pid, secao) {
    const p = produtores.find(x => x.id === pid);
    if (!p) return;
    aoCriarProdutor = null;
    editandoProdutorId = pid;
    $('modal-produtor-titulo').textContent = 'Editar produtor';
    preencherFormProdutor(p);
    $('modal-produtor').hidden = false;
    // "Editar" de um bloco da ficha abre o formulário já naquele bloco
    const folha = document.querySelector('#modal-produtor .modal-sheet');
    folha.scrollTop = 0;
    if (secao && $(secao)) setTimeout(() => { folha.scrollTop = Math.max(0, $(secao).offsetTop - 12); }, 30);
  }
  $('fab-add-produtor').addEventListener('click', () => abrirCadastroRapido());
  $('produtor-cancel').addEventListener('click', () => { aoCriarProdutor = null; editandoProdutorId = null; $('modal-produtor').hidden = true; });
  $('produtor-save').addEventListener('click', async () => {
    const dados = lerFormProdutor();
    if (!dados.nome) { avisar('Digite o nome do produtor.').then(() => $('produtor-nome-input').focus()); return; }
    if (!(await conferirCadastro(dados, editandoProdutorId))) return;
    const cb = aoCriarProdutor;
    const editando = editandoProdutorId;
    aoCriarProdutor = null;
    editandoProdutorId = null;
    $('modal-produtor').hidden = true;
    if (editando) {
      updateProdutor(editando, { ...dados, atualizadoPor: viewerId || null, atualizadoEm: Date.now() });
      registrarAtividade('editou', 'produtor', editando, dados.nome);
      if (currentProdutorId === editando) $('produtor-nome').textContent = dados.nome;
      return;
    }
    const id = await addProdutor(dados);
    if (!id) { avisar('Não foi possível cadastrar o produtor agora. Tente de novo.'); return; }
    if (cb) cb(id, dados.nome);
  });
  $('produtor-editar').addEventListener('click', () => { if (currentProdutorId) abrirEditarProdutor(currentProdutorId, 'pf-pessoais'); });

  // ---------- cadastro rápido: nome, WhatsApp, cidade e o ponto do GPS ----------
  // O resto aparece na ficha como "campos em branco · Completar". Tudo passa pela fila do app
  // (gravar), então funciona sem internet, e a OS aberta logo em seguida também.
  let crCallback = null, crLoc = null, crConfirmouDup = false, crTimerDup = null;

  // (49) 9 9999-9999 enquanto digita; no fim, com 10 números (fixo), vira (49) 9999-9999
  function mascaraTelefone(v, final) {
    let d = String(v || '').replace(/\D/g, '');
    if (d.length > 11 && d.startsWith('55')) d = d.slice(2);
    d = d.replace(/^0+/, '').slice(0, 11);
    if (!d) return '';
    if (d.length <= 2) return '(' + d;
    const ddd = d.slice(0, 2), r = d.slice(2);
    if (final && r.length === 8) return '(' + ddd + ') ' + r.slice(0, 4) + '-' + r.slice(4);
    if (r.length <= 1) return '(' + ddd + ') ' + r;
    if (r.length <= 5) return '(' + ddd + ') ' + r[0] + ' ' + r.slice(1);
    return '(' + ddd + ') ' + r[0] + ' ' + r.slice(1, 5) + '-' + r.slice(5);
  }
  // chave para achar o mesmo telefone: DDD + 8 últimos números (com ou sem o 9 da frente, com ou sem +55)
  function chaveTelefone(t) {
    let d = String(t || '').replace(/\D/g, '');
    if (d.length > 11 && d.startsWith('55')) d = d.slice(2);
    d = d.replace(/^0+/, '');
    return d.length >= 10 ? d.slice(0, 2) + d.slice(-8) : '';
  }
  // nomes parecidos: igual sem acento, com 1 ou 2 letras trocadas, um nome dentro do outro
  // ("Valdir Schneider" x "Valdir A. Schneider") ou mesmo primeiro e último nome
  const PALAVRAS_SOLTAS = ['de', 'da', 'do', 'das', 'dos', 'e'];
  function palavrasNome(s) {
    return normalizarBusca(s).replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w && !PALAVRAS_SOLTAS.includes(w));
  }
  function distanciaTexto(a, b) {
    if (!a.length) return b.length;
    if (!b.length) return a.length;
    let ant = Array.from({ length: b.length + 1 }, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      const cur = [i];
      for (let j = 1; j <= b.length; j++) cur[j] = Math.min(ant[j] + 1, cur[j - 1] + 1, ant[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      ant = cur;
    }
    return ant[b.length];
  }
  function nomesParecidos(a, b) {
    const pa = palavrasNome(a), pb = palavrasNome(b);
    if (!pa.length || !pb.length) return false;
    const ja = pa.join(' '), jb = pb.join(' ');
    if (ja === jb) return true;
    if (Math.min(ja.length, jb.length) >= 6 && distanciaTexto(ja, jb) <= (Math.max(ja.length, jb.length) >= 12 ? 2 : 1)) return true;
    const [menor, maior] = pa.length <= pb.length ? [pa, pb] : [pb, pa];
    if (menor.every(w => maior.includes(w))) return true;
    return pa.length > 1 && pb.length > 1 && pa[0] === pb[0] && pa[pa.length - 1] === pb[pb.length - 1];
  }
  // procura também nos arquivados: cadastrar de novo quem foi arquivado é o repetido mais comum
  function produtoresParecidos(nome, telefone) {
    const chave = chaveTelefone(telefone);
    const temNome = String(nome || '').trim().length >= 3;
    const out = [];
    produtoresTodos.forEach(p => {
      const mesmoTel = !!chave && chaveTelefone(p.telefone) === chave;
      if (mesmoTel || (temNome && nomesParecidos(nome, p.nome))) out.push({ p, motivo: mesmoTel ? 'mesmo WhatsApp' : 'nome parecido' });
    });
    return out.sort((a, b) => (a.motivo === 'mesmo WhatsApp' ? 0 : 1) - (b.motivo === 'mesmo WhatsApp' ? 0 : 1)).slice(0, 3);
  }
  // cidades já cadastradas, da mais usada para a menos usada
  function cidadesCadastradas() {
    const cont = {};
    produtoresTodos.forEach(p => { const c = (p.cidade || '').trim(); if (c) cont[c] = (cont[c] || 0) + 1; });
    return Object.keys(cont).sort((a, b) => cont[b] - cont[a] || a.localeCompare(b));
  }
  // "pinhalzinho" vira "Pinhalzinho" quando a cidade já existe (não cria duas no filtro)
  function cidadeCanonica(c) {
    const n = normalizarBusca(c);
    return (n && cidadesCadastradas().find(x => normalizarBusca(x) === n)) || c;
  }

  function crPintarCidades() {
    const termo = normalizarBusca($('cr-cidade').value.trim());
    const lista = cidadesCadastradas().filter(c => normalizarBusca(c) !== termo && (!termo || normalizarBusca(c).includes(termo))).slice(0, 6);
    const box = $('cr-cidades');
    box.innerHTML = '';
    lista.forEach(c => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'check-chip';
      b.textContent = c;
      b.addEventListener('mousedown', e => e.preventDefault());
      b.addEventListener('click', () => { $('cr-cidade').value = c; crPintarCidades(); });
      box.appendChild(b);
    });
    box.hidden = !lista.length;
  }
  function crConferirDuplicados() {
    const lista = produtoresParecidos($('cr-nome').value, $('cr-whats').value);
    const box = $('cr-dup-lista');
    box.innerHTML = '';
    lista.forEach(({ p, motivo }) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'cr-dup-item';
      b.innerHTML = '<span class="cr-dup-txt"><span class="cr-dup-nome"></span><span class="cr-dup-sub"></span></span><span class="cr-dup-acao"></span>';
      b.querySelector('.cr-dup-nome').textContent = p.nome || 'Sem nome';
      b.querySelector('.cr-dup-sub').textContent = [motivo, localDoProdutor(p), p.telefone, p.arquivado ? 'arquivado' : ''].filter(Boolean).join(' · ');
      b.querySelector('.cr-dup-acao').textContent = crCallback ? 'Usar este' : 'Abrir ficha';
      b.addEventListener('click', () => crUsarExistente(p));
      box.appendChild(b);
    });
    $('cr-dup').hidden = !lista.length;
    if (!lista.length) crConfirmouDup = false;
    return lista;
  }
  function crUsarExistente(p) {
    if (p.arquivado) {
      avisar(p.nome + ' está arquivado. Para usar de novo, abra Produtores → Filtros → Arquivados e toque em Restaurar.');
      return;
    }
    const cb = crCallback;
    fecharCadastroRapido();
    if (cb) { cb(p.id, p.nome); return; }
    openProdutor(p.id, { voltar: voltarDaTelaAtual() });
  }
  // para onde a ficha (ou a OS) volta, a partir da tela em que a pessoa está
  function voltarDaTelaAtual() {
    const v = document.body.dataset.view;
    if (v === 'produtor') return fichaVoltarPara;
    return v && VIEWS.includes(v) && !v.startsWith('p-') && v !== 'entrada' ? v : 'produtores';
  }
  function crDicaGps() {
    const st = $('cr-gps-st');
    st.textContent = 'Na propriedade, toque para guardar o ponto do GPS. Funciona sem internet.';
    st.className = 'campo-dica';
  }
  function abrirCadastroRapido(nomeInicial = '', callback = null) {
    if (!podeLancar('produtores')) { avisar('Você não tem permissão para cadastrar produtores.'); return; }
    crCallback = callback;
    crLoc = null;
    crConfirmouDup = false;
    $('cr-nome').value = nomeInicial || '';
    $('cr-whats').value = '';
    $('cr-cidade').value = '';
    crDicaGps();
    $('cr-gps').textContent = '📍 Usar minha localização';
    // escolhendo produtor para uma OS ou venda: só "Salvar" (o fluxo continua sozinho depois)
    const comOS = !callback && podeLancar('visitas');
    $('cr-salvar-os').hidden = !comOS;
    $('cr-salvar').textContent = comOS ? 'Só salvar · completo depois' : 'Salvar';
    $('cr-salvar').className = comOS ? 'btn-secondary' : 'btn-primary';
    crPintarCidades();
    crConferirDuplicados();
    $('modal-cadastro-rapido').hidden = false;
    setTimeout(() => { if (!$('modal-cadastro-rapido').hidden) $('cr-nome').focus(); }, 60);
  }
  function fecharCadastroRapido() {
    crCallback = null;
    clearTimeout(crTimerDup);
    $('modal-cadastro-rapido').hidden = true;
  }
  async function crSalvar(abrirOS) {
    const nome = $('cr-nome').value.trim();
    if (!nome) { avisar('Digite o nome do produtor.').then(() => $('cr-nome').focus()); return; }
    const telefone = mascaraTelefone($('cr-whats').value, true);
    if (telefone && !chaveTelefone(telefone)) { avisar('Confira o WhatsApp: faltam números (DDD e número).').then(() => $('cr-whats').focus()); return; }
    const dups = crConferirDuplicados();
    if (dups.length && !crConfirmouDup) {
      const quem = dups.map(d => d.p.nome + (d.motivo === 'mesmo WhatsApp' ? ' (mesmo WhatsApp)' : '')).join(', ');
      const ok = await abrirDialogo('Já existe um cadastro parecido: ' + quem + '. Cadastrar mesmo assim?', { ok: 'Cadastrar mesmo assim', cancelar: 'Voltar' });
      if (!ok) return;
      crConfirmouDup = true;
    }
    const dados = { nome, telefone, cidade: cidadeCanonica($('cr-cidade').value.trim()) };
    if (crLoc) Object.assign(dados, { lat: crLoc.lat, lng: crLoc.lng, localizacao: crLoc.lat.toFixed(6) + ', ' + crLoc.lng.toFixed(6) });
    const cb = crCallback;
    const voltar = voltarDaTelaAtual();
    fecharCadastroRapido();
    const id = await addProdutor(dados);
    if (!id) return;
    if (cb) { cb(id, nome); return; }
    if (abrirOS) { abrirNovaOSDoProdutor(id, voltar); return; }
    avisoRapido('Produtor cadastrado');
  }

  $('cr-whats').addEventListener('input', e => { e.target.value = mascaraTelefone(e.target.value); });
  $('cr-whats').addEventListener('blur', e => { e.target.value = mascaraTelefone(e.target.value, true); });
  ['cr-nome', 'cr-whats'].forEach(id => $(id).addEventListener('input', () => {
    crConfirmouDup = false;
    clearTimeout(crTimerDup);
    crTimerDup = setTimeout(crConferirDuplicados, 250);
  }));
  $('cr-cidade').addEventListener('input', crPintarCidades);
  $('cr-gps').addEventListener('click', () => {
    const st = $('cr-gps-st'), btn = $('cr-gps');
    if (!navigator.geolocation) { st.textContent = 'O GPS não está disponível neste aparelho.'; st.className = 'campo-dica alerta'; return; }
    st.textContent = 'Procurando o sinal do GPS…';
    st.className = 'campo-dica';
    btn.disabled = true;
    navigator.geolocation.getCurrentPosition(pos => {
      btn.disabled = false;
      crLoc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      const prec = Math.round(pos.coords.accuracy || 0);
      st.textContent = 'Localização guardada' + (prec ? ' (precisão de ' + prec + ' m)' : '') + '.';
      st.className = 'campo-dica ok';
      btn.textContent = '📍 Atualizar localização';
    }, err => {
      btn.disabled = false;
      st.textContent = err && err.code === 1 ? 'O GPS foi bloqueado. Libere a localização para o app nas configurações do celular e tente de novo.'
        : err && err.code === 3 ? 'O GPS demorou para responder. Vá para um lugar aberto e tente de novo.'
        : 'Não deu para pegar a localização agora. Tente de novo.';
      st.className = 'campo-dica alerta';
    }, { enableHighAccuracy: true, timeout: 20000, maximumAge: 30000 });
  });
  $('cr-salvar-os').addEventListener('click', () => crSalvar(true));
  $('cr-salvar').addEventListener('click', () => crSalvar(false));
  $('cr-cancelar').addEventListener('click', fecharCadastroRapido);
  // leva o que já foi digitado para o formulário completo
  $('cr-completo').addEventListener('click', () => {
    const cb = crCallback, nome = $('cr-nome').value.trim(), tel = mascaraTelefone($('cr-whats').value, true);
    const cidade = cidadeCanonica($('cr-cidade').value.trim()), loc = crLoc;
    fecharCadastroRapido();
    abrirNovoProdutor(nome, cb);
    if (tel) $('produtor-telefone-input').value = tel;
    if (cidade) $('produtor-cidade-input').value = cidade;
    if (loc) { $('produtor-local-input').value = loc.lat.toFixed(6) + ', ' + loc.lng.toFixed(6); mostrarDicaLocal(); }
  });
  // a mesma máscara no telefone do cadastro completo
  $('produtor-telefone-input').addEventListener('input', e => { e.target.value = mascaraTelefone(e.target.value); });
  $('produtor-telefone-input').addEventListener('blur', e => { e.target.value = mascaraTelefone(e.target.value, true); });

  let avisoRapidoTimer = null;
  function avisoRapido(msg) {
    const el = $('aviso-rapido');
    el.textContent = msg;
    el.hidden = false;
    clearTimeout(avisoRapidoTimer);
    avisoRapidoTimer = setTimeout(() => { el.hidden = true; }, 2600);
  }

  // contato, localização e botões de WhatsApp/mapa na página do produtor

  // ---------- checklist: revisão de ordenhadeira ----------
  // três pilares da revisão. Ids e rótulos antigos não mudam: OS antigas são convertidas de volta pelo rótulo.
  const REVISAO_GRUPOS = { vacuo: '1. Vácuo e força', pulsacao: '2. Pulsação e extração', higiene: '3. Higiene e condução', geral: 'Geral' };
  const REVISAO_ITENS = [
    { id: 'oleoBomba', label: 'Óleo da bomba', grupo: 'vacuo' },
    { id: 'correias', label: 'Correias', grupo: 'vacuo' },
    { id: 'polias', label: 'Alinhamento das polias', grupo: 'vacuo' },
    { id: 'lubrificador', label: 'Lubrificador de óleo', grupo: 'vacuo' },
    { id: 'reguladoraVacuo', label: 'Reguladora de vácuo', grupo: 'vacuo' },
    { id: 'kitReguladorServo', label: 'Kit do regulador servo assistido', grupo: 'vacuo' },
    { id: 'mangueiraVacuoPrincipal', label: 'Mangueira do vácuo principal', grupo: 'vacuo' },
    { id: 'mangueiraVacuoDupla', label: 'Mangueira do vácuo dupla', grupo: 'vacuo' },
    { id: 'regulagemMaquina', label: 'Regulagem da máquina', grupo: 'vacuo' },
    { id: 'teteiras', label: 'Teteiras', grupo: 'pulsacao' },
    { id: 'pulsadores', label: 'Troca dos reparos de pulsadores', grupo: 'pulsacao' },
    { id: 'regulagemPulsadores', label: 'Regulagem dos pulsadores', grupo: 'pulsacao' },
    { id: 'mangueiraCurta', label: 'Mangueira curta de pulsação', grupo: 'pulsacao' },
    { id: 'coletor', label: 'Coletor', grupo: 'pulsacao' },
    { id: 'medidores', label: 'Kit dos medidores de leite', grupo: 'pulsacao' },
    { id: 'membranaCorte', label: 'Membrana da válvula de corte', grupo: 'pulsacao' },
    { id: 'extracao', label: 'Cilindros da extração automática', grupo: 'pulsacao' },
    { id: 'mangueiraLeite', label: 'Mangueira do leite', grupo: 'higiene' },
    { id: 'unidadeFinal', label: 'Vedação da unidade final', grupo: 'higiene' },
    { id: 'limpezaTubulacao', label: 'Limpeza das tubulações (vácuo e leite)', grupo: 'higiene' },
    { id: 'sistemaLimpeza', label: 'Sistema de limpeza (velas/jetter)', grupo: 'higiene' },
    { id: 'dosadoras', label: 'Bombas dosadoras', grupo: 'higiene' },
    { id: 'tempAgua', label: 'Temperatura da água de lavagem', grupo: 'higiene' },
    { id: 'limpezaGeral', label: 'Limpeza geral', grupo: 'higiene' },
    { id: 'funcionamentoGeral', label: 'Funcionamento geral', grupo: 'geral' },
    { id: 'outros', label: 'Outros', grupo: 'geral' }
  ];
  function renderRevisaoItens(checked) {
    const container = $('revisao-itens');
    container.innerHTML = '';
    let grupo = null;
    REVISAO_ITENS.forEach(item => {
      if (item.grupo !== grupo) {
        grupo = item.grupo;
        const t = document.createElement('div');
        t.className = 'check-grupo';
        t.textContent = REVISAO_GRUPOS[grupo] || '';
        container.appendChild(t);
      }
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'check-chip';
      chip.dataset.item = item.id;
      chip.textContent = item.label;
      const on = !!(checked && checked[item.id]);
      chip.classList.toggle('on', on);
      chip.setAttribute('aria-pressed', on ? 'true' : 'false');
      chip.addEventListener('click', () => {
        const agora = !chip.classList.contains('on');
        chip.classList.toggle('on', agora);
        chip.setAttribute('aria-pressed', agora ? 'true' : 'false');
        renderProximaPreview();
      });
      container.appendChild(chip);
    });
  }
  function readRevisaoItens() {
    const out = {};
    $('revisao-itens').querySelectorAll('.check-chip').forEach(chip => { out[chip.dataset.item] = chip.classList.contains('on'); });
    return out;
  }
  function itensFeitosLabels(itens) {
    return REVISAO_ITENS.filter(i => itens && itens[i.id]).map(i => i.label);
  }
  // Mostra no formulário, ao vivo, quando fica a próxima revisão
  function renderProximaPreview() {
    const box = $('visita-proxima-box');
    const data = $('visita-data').value || todayISO();
    if (revisaoTemAlgo(readRevisaoItens())) {
      box.textContent = '📅 Próxima revisão: ' + fmtDate(addMonthsISO(data, MESES_ATE_REVISAO)) + ' (6 meses após esta visita)';
      box.classList.add('on');
    } else {
      box.textContent = 'Marque acima o que foi feito — a próxima revisão fica agendada automaticamente para 6 meses depois.';
      box.classList.remove('on');
    }
  }
  function revisaoTemAlgo(itens) {
    return !!itens && Object.values(itens).some(Boolean);
  }

  // O formulário da visita virou o formulário da Ordem de Serviço (bloco MANUTENÇÃO, mais abaixo).

  $('delete-produtor-btn').addEventListener('click', async () => {
    const id = currentProdutorId;
    if (!id || !ehAdmin()) return;
    const p = produtoresTodos.find(x => x.id === id) || {};
    const ok = await confirmar('Excluir de vez este produtor e todo o histórico de visitas dele? Isso não pode ser desfeito. (Para só tirar das listas, use Arquivar.)', 'Excluir de vez');
    if (!ok || currentProdutorId !== id) return;
    closeProdutorDetail();
    showView('produtores');
    ordensIndice.filter(o => o.produtorId === id).forEach(o => gravar('delete', 'ordens/' + o.id));
    deleteProdutorById(id);
    registrarAtividade('excluiu', 'produtor', id, p.nome);
  });
  $('arquivar-produtor-btn').addEventListener('click', async () => {
    const id = currentProdutorId;
    const p = produtoresTodos.find(x => x.id === id);
    if (!p || nivel('produtores') < 3) return;
    if (!(await confirmar('Arquivar ' + (p.nome || 'este produtor') + '? Ele some das listas, mas todo o histórico continua guardado e dá para restaurar.', 'Arquivar')) || currentProdutorId !== id) return;
    gravar('update', 'produtores/' + id, { arquivado: true, arquivadoPor: viewerId || null, arquivadoEm: Date.now() });
    registrarAtividade('arquivou', 'produtor', id, p.nome);
    closeProdutorDetail();
    showView('produtores');
  });
  $('restaurar-produtor-btn').addEventListener('click', () => {
    const id = currentProdutorId;
    const p = produtoresTodos.find(x => x.id === id);
    if (!p || nivel('produtores') < 3) return;
    gravar('update', 'produtores/' + id, { arquivado: false, restauradoPor: viewerId || null, restauradoEm: Date.now() });
    registrarAtividade('restaurou', 'produtor', id, p.nome);
  });

  // =====================================================
  // MÉDIA DE LEITE
  // =====================================================
  // Cada média salva fica em produtores/<id>/medias. A mais recente (pela data
  // final do período) também é copiada para o próprio produtor (campos leite*),
  // que é o que alimenta a ficha dele, a tabela geral e a comparação.
  let leiteProdutorId = null;
  let leiteVoltarPara = 'home';
  let mediasOrdem = 'producao';
  let mpProdutorId = null;
  let mpVoltarPara = 'medias';
  let mpMedias = [];
  let mpRenderToken = 0;

  function fmtL(n, casas = 1) {
    return (Number(n) || 0).toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas });
  }
  function fmtPctVar(frac) {
    return (frac > 0 ? '+' : '') + (frac * 100).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';
  }
  function fmtDataCurta(iso) {
    if (!iso) return '';
    const [y, m, d] = iso.split('-');
    return d + '/' + m + '/' + y.slice(2);
  }
  // Número de dias do período, contando o primeiro e o último
  function diasEntre(inicio, fim) {
    if (!inicio || !fim) return 0;
    const [a, b, c] = inicio.split('-').map(Number);
    const [x, y, z] = fim.split('-').map(Number);
    return Math.round((Date.UTC(x, y - 1, z) - Date.UTC(a, b - 1, c)) / 86400000) + 1;
  }
  function tendencia(atual, anterior) {
    if (!(atual > 0) || !(anterior > 0)) return null;
    const v = (atual - anterior) / anterior;
    if (Math.abs(v) < 0.0005) return { cls: 'igual', seta: '=', v: 0 };
    return v > 0 ? { cls: 'sobe', seta: '↑', v } : { cls: 'desce', seta: '↓', v };
  }
  function textoTendencia(t) {
    return t.cls === 'igual' ? '= igual à média anterior' : t.seta + ' ' + fmtPctVar(t.v) + ' vs média anterior';
  }
  function primeiroDiaDoMes() {
    const d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-01';
  }
  const porNome = (a, b) => (a.nome || '').localeCompare(b.nome || '');

  // ---- armazenamento das médias ----
  function ordenarMedias(lista) {
    return lista.slice().sort((a, b) => (a.dataFinal || '').localeCompare(b.dataFinal || '') || (a.criadoEm || 0) - (b.criadoEm || 0));
  }
  async function listarMedias(pid) { return ordenarMedias((await lerColecao('produtores/' + pid + '/medias')).filter(naoArquivado)); }
  // Copia a média mais recente (e a anterior, para a seta) para a ficha do produtor
  async function recalcularLeiteProdutor(pid) {
    const lista = await listarMedias(pid);
    const ult = lista[lista.length - 1] || null;
    const ant = lista[lista.length - 2] || null;
    const comVacas = lista.filter(m => m.vacas).pop() || null;
    updateProdutor(pid, {
      leiteMediaDia: ult ? ult.mediaDia : null,
      leiteMediaVaca: ult ? (ult.mediaVaca || null) : null,
      leiteVacas: comVacas ? comVacas.vacas : null,
      leitePeriodoInicio: ult ? ult.dataInicial : null,
      leitePeriodoFim: ult ? ult.dataFinal : null,
      leiteDataCalculo: ult ? ult.data : null,
      leiteSalvoPor: ult ? (ult.criadoPor || null) : null,
      leiteMediaAnterior: ant ? ant.mediaDia : null
    });
    return lista;
  }

  // ---- calculadora ----
  function abrirLeite(pid, voltarPara) {
    leiteVoltarPara = voltarPara || 'home';
    if (!$('leite-inicio').value) $('leite-inicio').value = primeiroDiaDoMes();
    if (!$('leite-fim').value) $('leite-fim').value = todayISO();
    if (pid) selecionarProdutorLeite(pid); else calcularLeite();
    showView('leite');
  }
  function lerFormLeite() {
    const litros = parseMoney($('leite-litros').value);
    const inicio = $('leite-inicio').value;
    const fim = $('leite-fim').value;
    const dias = diasEntre(inicio, fim);
    const vacas = parseInt($('leite-vacas').value, 10) || 0;
    const mediaDia = (litros > 0 && dias > 0) ? litros / dias : 0;
    const mediaVaca = (mediaDia > 0 && vacas > 0) ? mediaDia / vacas : 0;
    return { litros, inicio, fim, dias, vacas, mediaDia, mediaVaca, proj30: mediaDia * 30 };
  }
  function calcularLeite() {
    const f = lerFormLeite();
    $('leite-ver-ficha').hidden = !leiteProdutorId;
    const hint = $('leite-dias-hint');
    if (f.inicio && f.fim && f.dias <= 0) {
      hint.textContent = 'A data final precisa ser igual ou depois da data inicial.';
      hint.style.color = 'var(--tax)';
    } else if (f.dias > 0) {
      hint.textContent = f.dias + (f.dias === 1 ? ' dia' : ' dias') + ' no período (contando o primeiro e o último dia)';
      hint.style.color = '';
    } else {
      hint.textContent = '';
    }
    $('leite-media-dia').textContent = f.mediaDia > 0 ? fmtL(f.mediaDia) + ' L/dia' : '— L/dia';
    $('leite-media-vaca').textContent = f.mediaVaca > 0 ? fmtL(f.mediaVaca) + ' L' : (f.mediaDia > 0 ? 'informe as vacas' : '—');
    $('leite-proj30').textContent = f.mediaDia > 0 ? fmtL(f.proj30, 0) + ' L' : '—';
    $('leite-dias').textContent = f.dias > 0 ? String(f.dias) : '—';

    const p = produtores.find(x => x.id === leiteProdutorId);
    const anterior = p && p.leiteMediaDia > 0 ? p.leiteMediaDia : null;
    $('leite-anterior').textContent = anterior
      ? fmtL(anterior) + ' L/dia' + (p.leitePeriodoFim ? ' (até ' + fmtDataCurta(p.leitePeriodoFim) + ')' : '')
      : (leiteProdutorId ? 'nenhuma ainda' : '—');
    const t = tendencia(f.mediaDia, anterior);
    const el = $('leite-tendencia');
    if (t) {
      el.className = 'tendencia ' + t.cls;
      el.textContent = textoTendencia(t);
      el.hidden = false;
    } else {
      el.hidden = true;
    }
  }
  ['leite-litros', 'leite-inicio', 'leite-fim', 'leite-vacas'].forEach(id => {
    $(id).addEventListener('input', calcularLeite);
    $(id).addEventListener('change', calcularLeite);
  });

  // ---- escolher o produtor (busca + "+ Novo produtor") ----
  function renderPickerLeite() {
    const lista = $('leite-produtor-lista');
    const texto = $('leite-produtor-busca').value.trim();
    const termo = normalizarBusca(texto);
    const sel = produtores.find(p => p.id === leiteProdutorId);
    const mostrarTodos = !termo || (sel && normalizarBusca(sel.nome) === termo);
    const filtrados = produtores
      .filter(p => mostrarTodos || textoBuscaProdutor(p).includes(termo))
      .sort(porNome)
      .slice(0, 40);

    lista.innerHTML = '';
    if (!filtrados.length) {
      const v = document.createElement('div');
      v.className = 'picker-vazio';
      v.textContent = produtores.length ? 'Nenhum produtor com esse nome.' : 'Nenhum produtor cadastrado ainda.';
      lista.appendChild(v);
    }
    filtrados.forEach(p => {
      const it = document.createElement('div');
      it.className = 'picker-item' + (p.id === leiteProdutorId ? ' ativo' : '');
      it.innerHTML = '<div class="picker-nome"></div><div class="picker-sub"></div>';
      it.querySelector('.picker-nome').textContent = p.nome;
      it.querySelector('.picker-sub').textContent = [
        localDoProdutor(p),
        p.leiteMediaDia > 0 ? 'Última média: ' + fmtL(p.leiteMediaDia) + ' L/dia' : 'Sem média salva'
      ].filter(Boolean).join(' · ');
      it.addEventListener('mousedown', e => e.preventDefault()); // mantém o foco até o toque terminar
      it.addEventListener('click', () => selecionarProdutorLeite(p.id));
      lista.appendChild(it);
    });
    const novo = document.createElement('div');
    novo.className = 'picker-item novo';
    novo.dataset.perm = 'produtores:2';
    const sugerirNome = !mostrarTodos && !filtrados.some(p => normalizarBusca(p.nome) === termo);
    novo.textContent = '+ Novo produtor' + (sugerirNome ? ': "' + texto + '"' : '');
    novo.addEventListener('mousedown', e => e.preventDefault());
    novo.addEventListener('click', () => {
      fecharPickerLeite();
      abrirNovoProdutor(sugerirNome ? texto : '', (id, nome) => selecionarProdutorLeite(id, nome));
    });
    lista.appendChild(novo);
    lista.hidden = false;
  }
  function fecharPickerLeite() { $('leite-produtor-lista').hidden = true; }
  function selecionarProdutorLeite(id, nomeSeAindaNaoCarregou) {
    leiteProdutorId = id;
    const p = produtores.find(x => x.id === id);
    $('leite-produtor-busca').value = p ? p.nome : (nomeSeAindaNaoCarregou || '');
    $('leite-vacas').value = vacasDoProdutor(p) || '';
    fecharPickerLeite();
    $('leite-produtor-busca').blur();
    calcularLeite();
  }
  $('leite-produtor-busca').addEventListener('focus', () => { $('leite-produtor-busca').select(); renderPickerLeite(); });
  $('leite-produtor-busca').addEventListener('input', () => {
    const sel = produtores.find(p => p.id === leiteProdutorId);
    if (sel && normalizarBusca(sel.nome) !== normalizarBusca($('leite-produtor-busca').value.trim())) {
      leiteProdutorId = null;
      calcularLeite();
    }
    renderPickerLeite();
  });
  $('leite-produtor-busca').addEventListener('blur', () => {
    setTimeout(() => {
      fecharPickerLeite();
      // digitou o nome inteiro sem tocar na lista: escolhe esse produtor
      if (!leiteProdutorId) {
        const termo = normalizarBusca($('leite-produtor-busca').value.trim());
        const exato = termo && produtores.filter(p => normalizarBusca(p.nome) === termo);
        if (exato && exato.length === 1) selecionarProdutorLeite(exato[0].id);
      }
    }, 150);
  });

  // ---- salvar média ----
  async function salvarMedia() {
    const f = lerFormLeite();
    if (!leiteProdutorId) { avisar('Escolha o produtor na lista (ou toque em "+ Novo produtor").'); return; }
    if (!(f.litros > 0)) { avisar('Informe os litros produzidos no período.'); return; }
    if (!f.inicio || !f.fim) { avisar('Informe a data inicial e a data final.'); return; }
    if (f.dias <= 0) { avisar('A data final precisa ser igual ou depois da data inicial.'); return; }

    const pid = leiteProdutorId;
    const registro = {
      dataInicial: f.inicio, dataFinal: f.fim, dias: f.dias, litros: f.litros,
      vacas: f.vacas || null,
      mediaDia: r2(f.mediaDia),
      mediaVaca: f.vacas ? r2(f.mediaVaca) : null,
      projecao30: r2(f.proj30),
      criadoPor: viewerId, criadoEm: Date.now(), data: todayISO()
    };
    const btn = $('btn-salvar-media');
    btn.disabled = true;
    try {
      gravar('set', 'produtores/' + pid + '/medias/' + novoId(), registro);
      // o nº de vacas informado aqui passa a ser o do cadastro (e do PMLS)
      const prod = produtores.find(x => x.id === pid);
      if (f.vacas > 0 && prod && f.vacas !== vacasDoProdutor(prod)) updateProdutor(pid, { vacasLactacao: f.vacas, atualizadoPor: viewerId || null, atualizadoEm: Date.now() });
      await recalcularLeiteProdutor(pid);
    } catch (e) {
      btn.disabled = false;
      avisar('Não foi possível salvar a média agora. Verifique a conexão e tente de novo.');
      return;
    }
    btn.disabled = false;
    $('leite-litros').value = '';
    btn.textContent = 'Média salva ✓';
    setTimeout(() => { btn.textContent = '💾 Salvar média'; }, 1800);
    calcularLeite();
  }
  $('btn-salvar-media').addEventListener('click', salvarMedia);

  // ---- tabela de todos os produtores ----
  function produtoresOrdenadosMedias() {
    const com = produtores.filter(p => p.leiteMediaDia > 0);
    const sem = produtores.filter(p => !(p.leiteMediaDia > 0)).sort(porNome);
    if (mediasOrdem === 'nome') return produtores.slice().sort(porNome);
    if (mediasOrdem === 'vaca') {
      return com.sort((a, b) => (b.leiteMediaVaca || -1) - (a.leiteMediaVaca || -1) || b.leiteMediaDia - a.leiteMediaDia).concat(sem);
    }
    return com.sort((a, b) => b.leiteMediaDia - a.leiteMediaDia).concat(sem);
  }
  function renderMediasTabela() {
    const tbody = $('medias-tbody');
    tbody.innerHTML = '';
    const com = produtores.filter(p => p.leiteMediaDia > 0);
    const total = com.reduce((s, p) => s + Number(p.leiteMediaDia), 0);
    $('medias-total').textContent = fmtL(total) + ' L/dia';
    $('medias-total-sub').textContent = com.length + ' de ' + produtores.length +
      (produtores.length === 1 ? ' produtor' : ' produtores') + ' com média salva · ' + fmtL(total * 30, 0) + ' L em 30 dias';
    $('medias-empty').hidden = produtores.length > 0;
    $('medias-tabela-wrap').hidden = produtores.length === 0;

    produtoresOrdenadosMedias().forEach(p => {
      const tem = p.leiteMediaDia > 0;
      const t = tem ? tendencia(p.leiteMediaDia, p.leiteMediaAnterior) : null;
      const tr = document.createElement('tr');
      if (!tem) tr.className = 'sem-media';
      tr.innerHTML = '<td class="nome"></td><td class="num"></td><td class="num"></td><td class="num"></td><td class="seta"></td>';
      const td = tr.children;
      td[0].textContent = p.nome;
      if (localDoProdutor(p)) {
        const loc = document.createElement('div');
        loc.className = 'produtor-local';
        loc.style.fontWeight = '400';
        loc.textContent = localDoProdutor(p);
        td[0].appendChild(loc);
      }
      td[1].textContent = tem ? fmtL(p.leiteMediaDia) : '—';
      td[2].textContent = tem && p.leiteMediaVaca ? fmtL(p.leiteMediaVaca) : '—';
      td[3].textContent = tem ? fmtDataCurta(p.leiteDataCalculo) : '—';
      if (t) {
        td[4].textContent = t.seta;
        td[4].className = 'seta ' + t.cls;
        td[4].title = fmtPctVar(t.v);
      }
      tr.addEventListener('click', () => abrirMediasProdutor(p.id, 'medias'));
      tbody.appendChild(tr);
    });
  }
  $('medias-ordem').querySelectorAll('button').forEach(b => {
    b.addEventListener('click', () => {
      mediasOrdem = b.dataset.ordem;
      $('medias-ordem').querySelectorAll('button').forEach(x => x.classList.toggle('active', x === b));
      renderMediasTabela();
    });
  });

  // ---- histórico de um produtor + gráfico ----
  // O histórico de médias agora fica na aba Leite da ficha do produtor
  function abrirMediasProdutor(pid, voltarPara) {
    openProdutor(pid, { aba: 'leite', voltar: voltarPara === 'produtor' ? 'produtores' : (voltarPara || 'medias') });
  }
  async function carregarMediasProdutor() {
    const pid = mpProdutorId;
    const token = ++mpRenderToken;
    let lista;
    try { lista = await listarMedias(pid); }
    catch (e) {
      if (token === mpRenderToken) $('mp-grafico').innerHTML = '<div class="grafico-vazio">Não consegui carregar as médias agora.</div>';
      return;
    }
    let perfis = {};
    const ids = [...new Set(lista.map(m => m.criadoPor).filter(Boolean))];
    try {
      const user = await claude.use('user');
      if (user && ids.length) perfis = await user.profiles(ids);
    } catch (e) {}
    if (token !== mpRenderToken) return;
    mpMedias = lista;

    const ult = lista[lista.length - 1];
    const t = ult && lista.length > 1 ? tendencia(ult.mediaDia, lista[lista.length - 2].mediaDia) : null;
    $('mp-resumo').textContent = ult
      ? 'Última: ' + fmtL(ult.mediaDia) + ' L/dia' + (ult.mediaVaca ? ' · ' + fmtL(ult.mediaVaca) + ' L/vaca/dia' : '') + (t ? ' · ' + textoTendencia(t) : '')
      : '';

    const g = $('mp-grafico');
    g.innerHTML = '';
    g.appendChild(graficoLinha(lista.map(m => ({ data: m.dataFinal, valor: m.mediaDia }))));

    const box = $('mp-lista');
    box.innerHTML = '';
    $('mp-empty').hidden = lista.length > 0;
    lista.slice().reverse().forEach((m, i, arr) => {
      const anterior = arr[i + 1];
      const tm = anterior ? tendencia(m.mediaDia, anterior.mediaDia) : null;
      const autor = m.criadoPor && perfis[m.criadoPor] ? (perfis[m.criadoPor].name || '') : '';
      const card = document.createElement('div');
      card.className = 'record';
      card.innerHTML = `
        <div class="record-top">
          <span class="record-date"></span>
          <span class="record-x" title="Excluir">×</span>
        </div>
        <div class="media-linha"></div>
        <div class="media-sub"></div>
        ${autor ? '<div class="record-autor"></div>' : ''}
      `;
      card.querySelector('.record-date').textContent = fmtDataCurta(m.dataInicial) + ' a ' + fmtDataCurta(m.dataFinal);
      const linha = card.querySelector('.media-linha');
      linha.textContent = fmtL(m.mediaDia) + ' L/dia' + (m.mediaVaca ? ' · ' + fmtL(m.mediaVaca) + ' L/vaca' : '');
      if (tm) {
        const s = document.createElement('span');
        s.className = 'seta ' + tm.cls;
        s.textContent = '  ' + tm.seta + ' ' + fmtPctVar(tm.v);
        linha.appendChild(s);
      }
      card.querySelector('.media-sub').textContent =
        fmtL(m.litros, 0) + ' L em ' + m.dias + (m.dias === 1 ? ' dia' : ' dias') + (m.vacas ? ' · ' + m.vacas + ' vacas' : '');
      if (autor) card.querySelector('.record-autor').textContent = 'Salvo por ' + autor + ' em ' + fmtDate(m.data);
      card.querySelector('.record-x').hidden = !podeEditarRegistro('leite', m.criadoPor);
      card.querySelector('.record-x').addEventListener('click', async () => {
        const r = await removerRegistro({ modulo: 'leite', caminho: 'produtores/' + pid + '/medias/' + m.id, criadoPor: m.criadoPor,
          rotulo: 'a média de ' + fmtDataCurta(m.dataInicial) + ' a ' + fmtDataCurta(m.dataFinal) });
        if (!r) return;
        await recalcularLeiteProdutor(pid);
        if (mpProdutorId === pid) carregarMediasProdutor();
      });
      box.appendChild(card);
    });
  }
  async function excluirMedia(pid, mid) {
    try {
      gravar('delete', 'produtores/' + pid + '/medias/' + mid);
      await recalcularLeiteProdutor(pid);
    } catch (e) {
      avisar('Não foi possível excluir agora. Tente de novo.');
    }
    if (mpProdutorId === pid) carregarMediasProdutor();
  }

  // Gráfico de linha simples (SVG), eixo X proporcional às datas
  function graficoLinha(pontos) {
    const box = document.createElement('div');
    box.className = 'grafico';
    const validos = pontos.filter(p => p.data && p.valor > 0);
    if (validos.length < 2) {
      const msg = document.createElement('div');
      msg.className = 'grafico-vazio';
      msg.textContent = validos.length
        ? 'Salve mais uma média deste produtor para ver a evolução no gráfico.'
        : 'Nenhuma média salva ainda.';
      box.appendChild(msg);
      return box;
    }
    const W = 340, H = 190, L = 44, R = 16, T = 24, B = 28;
    const tempo = iso => { const [y, m, d] = iso.split('-').map(Number); return Date.UTC(y, m - 1, d); };
    const xs = validos.map(p => tempo(p.data));
    const ys = validos.map(p => p.valor);
    let x0 = Math.min(...xs), x1 = Math.max(...xs);
    if (x1 === x0) { x0 -= 86400000; x1 += 86400000; }
    let y0 = Math.min(...ys), y1 = Math.max(...ys);
    const folga = (y1 - y0) * 0.2 || y1 * 0.1 || 1;
    y0 = Math.max(0, y0 - folga);
    y1 = y1 + folga;
    const px = x => L + (x - x0) / (x1 - x0) * (W - L - R);
    const py = y => T + (1 - (y - y0) / (y1 - y0)) * (H - T - B);
    const pts = validos.map((p, i) => [px(xs[i]), py(ys[i])]);

    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', 'Evolução da média de litros por dia');
    const el = (tag, attrs, txt) => {
      const e = document.createElementNS(ns, tag);
      Object.keys(attrs).forEach(k => e.setAttribute(k, attrs[k]));
      if (txt != null) e.textContent = txt;
      svg.appendChild(e);
      return e;
    };
    [0, 0.5, 1].forEach(fr => {
      const v = y0 + (y1 - y0) * fr;
      const y = py(v);
      el('line', { x1: L, x2: W - R, y1: y, y2: y, class: 'g-grade' });
      el('text', { x: L - 6, y: y + 3.5, 'text-anchor': 'end', class: 'g-txt' }, fmtL(v, 0));
    });
    const d = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');
    const base = (H - B).toFixed(1);
    el('path', { d: d + ' L' + pts[pts.length - 1][0].toFixed(1) + ' ' + base + ' L' + pts[0][0].toFixed(1) + ' ' + base + ' Z', class: 'g-area' });
    el('path', { d, class: 'g-linha' });
    pts.forEach(p => el('circle', { cx: p[0].toFixed(1), cy: p[1].toFixed(1), r: 3.5, class: 'g-ponto' }));
    const u = pts[pts.length - 1];
    el('text', { x: u[0].toFixed(1), y: (u[1] - 9).toFixed(1), 'text-anchor': 'end', class: 'g-valor' }, fmtL(ys[ys.length - 1]));
    el('text', { x: pts[0][0].toFixed(1), y: H - 8, 'text-anchor': 'start', class: 'g-txt' }, fmtDataCurta(validos[0].data));
    el('text', { x: u[0].toFixed(1), y: H - 8, 'text-anchor': 'end', class: 'g-txt' }, fmtDataCurta(validos[validos.length - 1].data));
    box.appendChild(svg);
    return box;
  }

  // ---- ficha do produtor (página do produtor) ----
  function renderProdutorLeite() {
    const p = produtores.find(x => x.id === currentProdutorId);
    const el = $('produtor-leite-resumo');
    if (!p || !(p.leiteMediaDia > 0)) {
      el.textContent = 'Nenhuma média de leite salva ainda.';
      return;
    }
    const partes = [fmtL(p.leiteMediaDia) + ' L/dia'];
    if (p.leiteMediaVaca) partes.push(fmtL(p.leiteMediaVaca) + ' L/vaca/dia');
    if (p.leiteMediaVaca && p.leiteVacas) partes.push(p.leiteVacas + ' vacas');
    const t = tendencia(p.leiteMediaDia, p.leiteMediaAnterior);
    el.innerHTML = '<div class="leite-ficha-valor"></div><div class="leite-ficha-sub"></div>';
    el.children[0].textContent = partes.join(' · ');
    el.children[1].textContent = 'Período ' + fmtDate(p.leitePeriodoInicio) + ' a ' + fmtDate(p.leitePeriodoFim) +
      (t ? ' · ' + textoTendencia(t) : '');
  }

  // ---- exportar a tabela de médias em Excel ----
  $('btn-exportar-medias').addEventListener('click', async () => {
    const btn = $('btn-exportar-medias');
    const texto = btn.textContent;
    if (!produtores.length) { avisar('Nenhum produtor cadastrado ainda.'); return; }
    btn.disabled = true;
    btn.textContent = 'Gerando planilha…';
    try {
      const downloads = await claude.use('downloads');
      if (!downloads) { avisar('Exportar arquivos não está disponível aqui.'); return; }
      const ids = [...new Set(produtores.map(p => p.leiteSalvoPor).filter(Boolean))];
      let perfis = {};
      try {
        const user = await claude.use('user');
        if (user && ids.length) perfis = await user.profiles(ids);
      } catch (e) {}
      const linhas = produtoresOrdenadosMedias().map(p => {
        const tem = p.leiteMediaDia > 0;
        const t = tem ? tendencia(p.leiteMediaDia, p.leiteMediaAnterior) : null;
        return {
          produtor: p.nome || '',
          mediaDia: tem ? r2(p.leiteMediaDia) : null,
          mediaVaca: tem && p.leiteMediaVaca ? r2(p.leiteMediaVaca) : null,
          vacas: tem && p.leiteMediaVaca && p.leiteVacas ? Number(p.leiteVacas) : null,
          inicio: tem ? p.leitePeriodoInicio : null,
          fim: tem ? p.leitePeriodoFim : null,
          dataCalculo: tem ? p.leiteDataCalculo : null,
          variacao: t ? Math.round(t.v * 10000) / 10000 : null,
          salvoPor: tem && p.leiteSalvoPor && perfis[p.leiteSalvoPor] ? (perfis[p.leiteSalvoPor].name || '') : ''
        };
      });
      let ExcelJS;
      try { ExcelJS = await carregarExcelJS(); }
      catch (e) { avisar('Não consegui carregar o gerador de planilhas. Verifique a internet e tente de novo.'); return; }
      const bytes = await montarPlanilhaMedias(ExcelJS, linhas);
      const arquivo = new Blob([bytes], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      try {
        await downloads.save({ filename: nomeArquivoDemo('ordenha360-medias-' + todayISO() + '.xlsx'), data: arquivo });
      } catch (e) {
        const code = e && e.code;
        if (code === 'declined') return;
        if (code === 'rate_limited') { avisar('Já tem um download aberto. Conclua ou feche ele e tente de novo.'); return; }
        if (['unavailable', 'not_granted', 'capability_disabled', 'capability_removed', 'extension_not_enabled'].includes(code)) {
          avisar('Exportar arquivos não está disponível aqui.');
          return;
        }
        avisar('Não foi possível salvar a planilha' + (e && e.message ? ': ' + e.message : '.'));
      }
    } finally {
      btn.disabled = false;
      btn.textContent = texto;
    }
  });

  // ---- navegação ----
  $('nav-leite').addEventListener('click', () => abrirLeite(null, 'setor'));
  $('back-leite').addEventListener('click', () => showView(leiteVoltarPara));
  var mediasVoltarPara = 'leite';
  $('btn-ver-medias').addEventListener('click', () => { mediasVoltarPara = 'leite'; renderMediasTabela(); showView('medias'); });
  $('back-medias').addEventListener('click', () => { if (mediasVoltarPara === 'leite') calcularLeite(); showView(mediasVoltarPara || 'leite'); });
  $('produtor-leite-calc').addEventListener('click', () => abrirLeite(currentProdutorId, 'produtor'));

  // =====================================================
  // VENDAS
  // =====================================================
  // Todas as vendas ficam numa coleção só ("vendas"), para o resumo do mês juntar
  // todos os produtores. O produtor é o mesmo cadastro de Visitas e Média de leite.
  // O preço de cada item sai da mesma fórmula da Calculadora de margem:
  // (custo − ICMS da origem) ÷ divisor, com divisor = (80 − margem) ÷ 100.
  const PAGAMENTOS = { avista: 'À vista', prazo: 'A prazo', folha: 'Desconto em folha do leite' };
  let vendas = [];
  let vendaProdutorId = null;
  let formItens = [];
  let formComissaoBase = 'venda';
  let editandoVendaId = null;
  let vendaVoltarPara = 'vendas';
  let vendaAbertaId = null;
  let vdVoltarPara = 'vendas';
  let vendasRenderToken = 0;
  var formModo = 'venda', orcEditandoId = null, vendaFormSalva = false, formOrigem = 'manual', formAberto = false;   // o formulário serve à venda e ao orçamento
  let perfisVendas = {};

  // ---- armazenamento ----
  function aoMudarVendas() {
    if (!$('view-vendas').hidden) renderResumoVendas();
    if (!$('view-venda').hidden) renderVendaDetalhe();
    if (currentProdutorId) renderProdutorCompras();
    if (currentProdutorId && abaFicha === 'dados' && !$('view-produtor').hidden) renderFichaDados();
  }
  function atualizarVenda(id, campos) {
    return gravar('update', 'vendas/' + id, { ...campos, atualizadoPor: viewerId || null, atualizadoEm: Date.now() });
  }

  // ---- contas ----
  function nomeProdutorDaVenda(v) {
    const p = produtores.find(x => x.id === v.produtorId);
    return (p && p.nome) || v.produtorNome || 'Produtor removido';
  }
  function fmtPct1(frac) {
    return ((Number(frac) || 0) * 100).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';
  }
  function fmtQtd(n) { return (Number(n) || 0).toLocaleString('pt-BR', { maximumFractionDigits: 3 }); }
  function fmtMoedaCampo(n) {
    return (Number(n) || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  function aliquotaDaOrigem(o) { return o === 'fora' ? Number(config.icmsFora) : Number(config.icmsDentro); }
  function precoPelaFormula(custo, origem, margem) {
    const divisor = (80 - margem) / 100;
    if (!(custo > 0) || !(divisor > 0)) return 0;
    return (custo - custo * aliquotaDaOrigem(origem) / 100) / divisor;
  }
  // categorias do catálogo de peças
  const CATEGORIAS = { ordenha: 'Ordenha', resfriador: 'Resfriador', aguaquente: 'Água quente', conforto: 'Conforto animal', quimicos: 'Químicos', eletrica: 'Elétrica', outros: 'Outros' };
  // preço de venda de um item (uma conta só no app todo):
  //  · sem preço (semPreco): 0, o app mostra "preço a definir"
  //  · tabela que já é de venda (precoFinal): o preço da tabela, sem conta
  //  · senão: a fórmula da Calculadora, com a margem do item (ou a padrão das configurações)
  function precoVendaDoItem(item, margem) {
    if (!item || item.semPreco) return 0;
    const custo = Number(item.custo != null ? item.custo : item.custoUnit) || 0;
    if (item.precoFinal) return r2(custo);
    const m = margem == null || margem === '' ? Number(config.margemPadrao) : Number(margem);
    return r2(precoPelaFormula(custo, item.origem, m));
  }
  function totaisDosItens(itens) {
    let custo = 0, venda = 0;
    itens.forEach(i => {
      const q = Number(i.quantidade) || 0;
      custo += q * (Number(i.custoUnit) || 0);
      venda += q * (Number(i.precoUnit) || 0);
    });
    const lucro = venda - custo;
    return { custo, venda, lucro, margem: venda > 0 ? lucro / venda : 0 };
  }
  function calcComissao(totais, pct, base) {
    const sobre = base === 'lucro' ? Math.max(0, totais.lucro) : totais.venda;
    return sobre * (Number(pct) || 0) / 100;
  }
  function textoBase(base) { return base === 'lucro' ? 'sobre o lucro' : 'sobre o valor bruto da venda'; }
  function mesAtualISO() { return todayISO().slice(0, 7); }
  function resumoItens(itens) {
    return (itens || []).map(i => fmtQtd(i.quantidade) + '× ' + i.produto).join(', ');
  }

  // ---- escolher produtor (mesma busca da Média de leite, com "+ Novo produtor") ----
  function montarPickerProdutor(cfg) {
    const input = $(cfg.inputId), lista = $(cfg.listaId);
    const fechar = () => { lista.hidden = true; };
    function escolher(id, nomeSeAindaNaoCarregou) {
      cfg.set(id);
      const p = produtores.find(x => x.id === id);
      input.value = p ? p.nome : (nomeSeAindaNaoCarregou || '');
      fechar();
      input.blur();
    }
    function render() {
      const texto = input.value.trim();
      const termo = normalizarBusca(texto);
      const sel = produtores.find(p => p.id === cfg.get());
      const todos = !termo || (sel && normalizarBusca(sel.nome) === termo);
      const filtrados = produtores.filter(p => todos || textoBuscaProdutor(p).includes(termo)).sort(porNome).slice(0, 40);
      lista.innerHTML = '';
      if (!filtrados.length) {
        const v = document.createElement('div');
        v.className = 'picker-vazio';
        v.textContent = produtores.length ? 'Nenhum produtor com esse nome.' : 'Nenhum produtor cadastrado ainda.';
        lista.appendChild(v);
      }
      filtrados.forEach(p => {
        const it = document.createElement('div');
        it.className = 'picker-item' + (p.id === cfg.get() ? ' ativo' : '');
        it.innerHTML = '<div class="picker-nome"></div><div class="picker-sub"></div>';
        it.querySelector('.picker-nome').textContent = p.nome;
        it.querySelector('.picker-sub').textContent = localDoProdutor(p) || 'Sem linha/cidade cadastrada';
        it.addEventListener('mousedown', e => e.preventDefault());
        it.addEventListener('click', () => escolher(p.id));
        lista.appendChild(it);
      });
      const sugerir = !todos && !filtrados.some(p => normalizarBusca(p.nome) === termo);
      const novo = document.createElement('div');
      novo.className = 'picker-item novo';
      novo.dataset.perm = 'produtores:2';
      novo.textContent = '+ Novo produtor' + (sugerir ? ': "' + texto + '"' : '');
      novo.addEventListener('mousedown', e => e.preventDefault());
      novo.addEventListener('click', () => {
        fechar();
        abrirCadastroRapido(sugerir ? texto : '', (id, nome) => escolher(id, nome));
      });
      lista.appendChild(novo);
      lista.hidden = false;
    }
    input.addEventListener('focus', () => { input.select(); render(); });
    input.addEventListener('input', () => {
      const sel = produtores.find(p => p.id === cfg.get());
      if (sel && normalizarBusca(sel.nome) !== normalizarBusca(input.value.trim())) cfg.set(null);
      render();
    });
    input.addEventListener('blur', () => {
      setTimeout(() => {
        fechar();
        if (!cfg.get()) {
          const termo = normalizarBusca(input.value.trim());
          const exato = termo && produtores.filter(p => normalizarBusca(p.nome) === termo);
          if (exato && exato.length === 1) escolher(exato[0].id);
        }
      }, 150);
    });
    return { escolher };
  }
  montarPickerProdutor({
    inputId: 'venda-produtor-busca', listaId: 'venda-produtor-lista',
    get: () => vendaProdutorId, set: (id) => { vendaProdutorId = id; $('venda-ver-ficha').hidden = !id; }
  });

  // ---- formulário da venda ----
  function novoItem() {
    return {
      produto: '', marcaId: '', origem: 'dentro', quantidade: 1, custoUnit: 0,
      margem: config.margemPadrao, precoUnit: 0, precoManual: false
    };
  }
  function atualizarSugestoesProdutos() {
    const nomes = new Map();
    vendas.forEach(v => (v.itens || []).forEach(i => { const k = normalizarBusca(i.produto); if (k && !nomes.has(k)) nomes.set(k, i.produto); }));
    calculos.forEach(c => { const k = normalizarBusca(c.produto); if (k && !nomes.has(k)) nomes.set(k, c.produto); });
    const dl = $('lista-produtos-vendidos');
    dl.innerHTML = '';
    [...nomes.values()].sort((a, b) => a.localeCompare(b)).forEach(n => {
      const o = document.createElement('option'); o.value = n; dl.appendChild(o);
    });
  }
  function abrirFormVenda(venda, opcoes = {}) {
    formModo = 'venda'; orcEditandoId = null; vendaFormSalva = false; formAberto = true;
    formOrigem = opcoes.origem || 'manual';
    $('venda-saiu-estoque').checked = !!(venda && venda.saiuEstoque);
    $('venda-estoque-campo').hidden = !podeVer('visitas') || !!(venda && venda.origem === 'os');   // a OS já baixa as peças dela
    editandoVendaId = venda ? venda.id : null;
    vendaVoltarPara = opcoes.voltarPara || (venda ? 'venda' : 'vendas');
    $('venda-form-titulo').textContent = venda ? 'Editar venda' : 'Registrar venda';
    $('venda-data').value = venda ? venda.data : todayISO();
    $('venda-pagamento').value = venda ? (venda.pagamento || 'avista') : 'avista';
    $('venda-obs').value = venda ? (venda.observacao || '') : (opcoes.observacao || '');
    const pct = venda ? venda.comissaoPct : config.comissaoPct;
    $('venda-comissao-pct').value = String(pct == null ? '' : pct).replace('.', ',');
    $('venda-comissao-pct').disabled = nivel('comissoes') < 2;
    formComissaoBase = venda ? (venda.comissaoBase || 'venda') : config.comissaoBase;
    formItens = venda ? (venda.itens || []).map(i => ({ ...i })) : (opcoes.itens && opcoes.itens.length ? opcoes.itens.map(i => ({ ...novoItem(), ...i })) : [novoItem()]);
    if (!formItens.length) formItens = [novoItem()];
    vendaProdutorId = venda ? venda.produtorId : (opcoes.produtorId || null);
    $('venda-ver-ficha').hidden = !vendaProdutorId;
    const p = produtores.find(x => x.id === vendaProdutorId);
    $('venda-produtor-busca').value = p ? p.nome : (venda ? (venda.produtorNome || '') : '');
    atualizarSugestoesProdutos();
    renderItensVenda();
    pintarModoForm();
    showView('venda-form');
  }
  function renderItensVenda() {
    const box = $('venda-itens');
    box.innerHTML = '';
    formItens.forEach((it, i) => box.appendChild(cartaoItem(it, i)));
    atualizarTotaisForm();
  }
  function opcoesMarcas(sel, marcaId) {
    sel.innerHTML = '';
    const o0 = document.createElement('option');
    o0.value = ''; o0.textContent = 'Sem marca / outro fornecedor';
    sel.appendChild(o0);
    brands.slice().sort((a, b) => (a.name || '').localeCompare(b.name || '')).forEach(b => {
      const o = document.createElement('option');
      o.value = b.id;
      o.textContent = b.name + (b.origem === 'fora' ? ' · fora de SC' : ' · dentro de SC');
      sel.appendChild(o);
    });
    sel.value = brands.some(b => b.id === marcaId) ? marcaId : '';
  }
  function cartaoItem(it, i) {
    const pre = 'item-' + i + '-';
    const card = document.createElement('div');
    card.className = 'item-venda';
    card.innerHTML = `
      <div class="item-topo">
        <span class="item-titulo"></span>
        <button type="button" class="item-remover">Remover</button>
      </div>
      <div class="field">
        <label for="${pre}produto">Produto</label>
        <div class="cat-campo">
          <input type="text" id="${pre}produto" class="it-produto" list="lista-produtos-vendidos" placeholder="Ex: Teteira de silicone" autocomplete="off">
          <button type="button" class="btn-secondary cat-btn it-catalogo"><svg class="ic" aria-hidden="true"><use href="#i-package"/></svg>Catálogo</button>
        </div>
      </div>
      <div class="field">
        <label for="${pre}marca">Marca / fornecedor</label>
        <select id="${pre}marca" class="it-marca"></select>
      </div>
      <div class="item-origem">
        <div class="toggle it-origem">
          <button type="button" data-o="dentro">Dentro de SC</button>
          <button type="button" data-o="fora">Fora de SC</button>
        </div>
      </div>
      <div class="rate-row">
        <div class="field">
          <label for="${pre}qtd">Quantidade</label>
          <input type="text" inputmode="decimal" id="${pre}qtd" class="it-qtd mono-input">
        </div>
        <div class="field" data-perm="custos:1">
          <label for="${pre}custo">Custo unit. (R$)</label>
          <input type="text" inputmode="decimal" id="${pre}custo" class="it-custo mono-input" placeholder="0,00">
        </div>
      </div>
      <div class="rate-row">
        <div class="field" data-perm="custos:1">
          <label for="${pre}margem">Margem (%)</label>
          <input type="text" inputmode="decimal" id="${pre}margem" class="it-margem mono-input">
        </div>
        <div class="field">
          <label for="${pre}preco">Preço unit. (R$)</label>
          <input type="text" inputmode="decimal" id="${pre}preco" class="it-preco mono-input" placeholder="0,00">
          <div class="preco-manual" hidden><span>editado à mão</span><button type="button" class="it-recalc">usar a fórmula</button></div>
        </div>
      </div>
      <div class="item-resumo"><span>Subtotal <strong class="it-subtotal"></strong></span><span class="ir-lucro" data-perm="custos:1"></span></div>`;
    const q = s => card.querySelector(s);
    q('.item-titulo').textContent = 'Item ' + (i + 1);
    q('.it-produto').value = it.produto || '';
    opcoesMarcas(q('.it-marca'), it.marcaId);
    q('.it-qtd').value = fmtQtd(it.quantidade);
    q('.it-custo').value = it.custoUnit ? fmtMoedaCampo(it.custoUnit) : '';
    q('.it-margem').value = String(it.margem == null ? '' : it.margem).replace('.', ',');
    q('.it-preco').value = it.precoUnit ? fmtMoedaCampo(it.precoUnit) : '';

    const pintarOrigem = () => {
      q('.it-origem').querySelectorAll('button').forEach(b => b.classList.toggle('active', b.dataset.o === it.origem));
    };
    // recalcular=false na abertura: numa venda salva o preço fica como foi gravado
    const atualizar = (recalcular = true) => {
      if (recalcular && !it.precoManual) {
        it.precoUnit = precoVendaDoItem({ custo: it.custoUnit, origem: it.origem }, it.margem);
        if (document.activeElement !== q('.it-preco')) q('.it-preco').value = it.precoUnit ? fmtMoedaCampo(it.precoUnit) : '';
      }
      q('.preco-manual').hidden = !it.precoManual;
      const qtd = Number(it.quantidade) || 0;
      const subtotal = qtd * (Number(it.precoUnit) || 0);
      const lucro = qtd * ((Number(it.precoUnit) || 0) - (Number(it.custoUnit) || 0));
      q('.it-subtotal').textContent = fmt(subtotal);
      q('.ir-lucro').textContent = subtotal > 0
        ? 'lucro ' + fmt(lucro) + ' (' + fmtPct1(lucro / subtotal) + ')'
        : '';
      atualizarTotaisForm();
    };
    pintarOrigem();

    q('.it-produto').addEventListener('input', e => { it.produto = e.target.value; it.pecaId = null; it.catId = null; it.codigo = ''; });
    q('.it-marca').addEventListener('change', e => {
      it.marcaId = e.target.value;
      const marca = brands.find(b => b.id === it.marcaId);
      it.marcaNome = marca ? marca.name : '';
      if (marca) { it.origem = marca.origem === 'fora' ? 'fora' : 'dentro'; pintarOrigem(); }
      atualizar();
    });
    q('.it-origem').querySelectorAll('button').forEach(b => b.addEventListener('click', () => {
      it.origem = b.dataset.o; pintarOrigem(); atualizar();
    }));
    q('.it-qtd').addEventListener('input', e => { it.quantidade = parseMoney(e.target.value); atualizar(); });
    q('.it-custo').addEventListener('input', e => { it.custoUnit = parseMoney(e.target.value); atualizar(); });
    q('.it-margem').addEventListener('input', e => {
      it.margem = parseNum(e.target.value);
      it.precoManual = false; // mudar a margem volta a usar a fórmula
      atualizar();
    });
    q('.it-preco').addEventListener('input', e => {
      it.precoUnit = parseMoney(e.target.value);
      it.precoManual = true;
      atualizar();
    });
    q('.it-preco').addEventListener('blur', e => { if (it.precoUnit) e.target.value = fmtMoedaCampo(it.precoUnit); });
    q('.it-recalc').addEventListener('click', () => { it.precoManual = false; atualizar(); });
    // catálogo único: produto, marca, origem e custo da tabela; o preço sai pela fórmula da margem
    q('.it-catalogo').addEventListener('click', () => abrirCatalogo({ onde: 'venda', aoEscolher: c => {
      if (c.avulsa) { if (c.texto) { it.produto = c.texto; q('.it-produto').value = it.produto; } return; }
      it.produto = nomeItemCatalogo(c);
      it.pecaId = c.pecaId || null; it.catId = c.id; it.codigo = c.codigo || ''; it.categoria = c.categoria || 'outros'; it.marcaNome = c.marca || '';
      q('.it-produto').value = it.produto;
      if (c.precoFinal) {
        // kit próprio: o preço da tabela já é o de venda; o custo fica em branco
        it.custoUnit = 0;
        it.precoUnit = r2(c.custo);
        it.precoManual = true;
        it.marcaId = '';   // não fica a marca de um item escolhido antes
        opcoesMarcas(q('.it-marca'), '');
        q('.it-custo').value = '';
        q('.it-preco').value = fmtMoedaCampo(it.precoUnit);
        avisoRapido('Preço de venda (tabela própria): o custo fica em branco.');
      } else {
        let marca = marcaComNome(c.marca), id = marca ? marca.id : '';
        if (!marca && c.marca && nivel('calc') >= 2) id = criarMarca(c.marca, c.origem);
        it.marcaId = id;
        opcoesMarcas(q('.it-marca'), id);
        // marca acabada de criar: ainda não chegou na lista, entra na hora
        if (id && q('.it-marca').value !== id) {
          const o = document.createElement('option');
          o.value = id; o.textContent = c.marca + (c.origem === 'fora' ? ' · fora de SC' : ' · dentro de SC');
          q('.it-marca').appendChild(o); q('.it-marca').value = id;
        }
        it.origem = c.origem === 'fora' ? 'fora' : 'dentro';
        pintarOrigem();
        it.custoUnit = c.custo > 0 && !c.precoManual ? r2(c.custo) : 0;
        q('.it-custo').value = it.custoUnit ? fmtMoedaCampo(it.custoUnit) : '';
        it.precoManual = !!c.precoManual;
        if (c.precoManual) { it.precoUnit = r2(c.precoVenda); q('.it-preco').value = fmtMoedaCampo(it.precoUnit); }
      }
      atualizar();
    } }));
    q('.item-remover').addEventListener('click', () => {
      if (formItens.length === 1) { formItens = [novoItem()]; } else { formItens.splice(i, 1); }
      renderItensVenda();
    });
    integItemCard(card, it, i, atualizar);
    atualizar(!it.precoUnit);
    return card;
  }
  function atualizarTotaisForm() {
    const tot = totaisDosItens(formItens);
    const pct = parseMoney($('venda-comissao-pct').value);
    $('vf-total').textContent = fmt(tot.venda);
    $('vf-custo').textContent = fmt(tot.custo);
    $('vf-lucro').textContent = fmt(tot.lucro);
    $('vf-margem').textContent = fmtPct1(tot.margem);
    $('vf-comissao').textContent = fmt(calcComissao(tot, pct, formComissaoBase)) + ' (' + fmtL(pct, 1) + '% ' + textoBase(formComissaoBase) + ')';
    $('venda-comissao-dica').textContent = 'Calculada ' + textoBase(formComissaoBase) +
      '. O padrão das configurações é ' + fmtL(config.comissaoPct, 1) + '%.';
  }
  $('venda-comissao-pct').addEventListener('input', atualizarTotaisForm);
  $('venda-add-item').addEventListener('click', () => {
    formItens.push(novoItem());
    renderItensVenda();
    const ultimo = $('item-' + (formItens.length - 1) + '-produto');
    if (ultimo) ultimo.focus();
  });

  // os itens como vão para o banco: o mesmo formato na venda e no orçamento
  function itensParaGravar(itens) {
    return itens.map(i => {
      const marca = brands.find(b => b.id === i.marcaId);
      return {
        pecaId: i.pecaId || null, catId: i.catId || null, codigo: i.codigo || '', categoria: i.categoria || categoriaPorPalavra(i.produto),
        produto: i.produto.trim(), marcaId: i.marcaId || '', marcaNome: marca ? marca.name : (i.marcaNome || ''),
        origem: i.origem === 'fora' ? 'fora' : 'dentro', aliquota: aliquotaDaOrigem(i.origem),
        quantidade: Number(i.quantidade), custoUnit: r2(i.custoUnit), margem: Number(i.margem) || 0,
        precoUnit: r2(i.precoUnit), precoManual: !!i.precoManual, ...(i.unidade ? { unidade: i.unidade } : {}), ...(i.grupo ? { grupo: i.grupo } : {}), ...integCamposItem(i)
      };
    });
  }
  async function salvarVenda() {
    if (!integValidarItens(formItens)) return;
    if (!vendaProdutorId) { avisar('Escolha o produtor na lista (ou toque em "+ Novo produtor").'); return; }
    const data = $('venda-data').value;
    if (!data) { avisar('Informe a data da venda.'); return; }
    const itens = formItens.filter(i => (i.produto || '').trim() || i.custoUnit > 0 || i.precoUnit > 0);
    if (!itens.length) { avisar('Adicione pelo menos um item com produto, quantidade e preço de venda.'); return; }
    const faltando = itens.findIndex(i => !(i.produto || '').trim() || !(i.quantidade > 0) || !(i.precoUnit > 0));
    if (faltando >= 0) { avisar('Confira o item ' + (faltando + 1) + ': precisa ter produto, quantidade e preço de venda.'); return; }

    const p = produtores.find(x => x.id === vendaProdutorId);
    const itensSalvos = itensParaGravar(itens);
    const tot = totaisDosItens(itensSalvos);
    const pct = parseMoney($('venda-comissao-pct').value);
    const registro = {
      produtorId: vendaProdutorId, produtorNome: p ? p.nome : '', data,
      itens: itensSalvos, pagamento: $('venda-pagamento').value, observacao: $('venda-obs').value.trim(),
      custoTotal: r2(tot.custo), valorTotal: r2(tot.venda), lucro: r2(tot.lucro),
      margem: Math.round(tot.margem * 10000) / 10000,
      comissaoPct: pct, comissaoBase: formComissaoBase, comissaoValor: r2(calcComissao(tot, pct, formComissaoBase))
    };

    const antesV = editandoVendaId ? (vendasTodas.find(x => x.id === editandoVendaId) || null) : null;
    if (!antesV) registro.origem = formOrigem || 'manual';
    const saiu = $('venda-estoque-campo').hidden ? !!(antesV && antesV.saiuEstoque) : $('venda-saiu-estoque').checked;
    registro.saiuEstoque = saiu;
    registro.estoqueTecnico = saiu ? ((antesV && antesV.estoqueTecnico) || viewerId || null) : null;
    const integ = await integAntesDeGravar(registro, editandoVendaId);
    let id = editandoVendaId;
    if (id) {
      gravar('update', 'vendas/' + id, { ...registro, atualizadoPor: viewerId || null, atualizadoEm: Date.now() });
    } else {
      id = novoId();
      Object.assign(registro, { criadoPor: viewerId || null, criadoEm: Date.now(), comissaoRecebida: false, comissaoRecebidaEm: null });
      gravar('set', 'vendas/' + id, registro);
    }
    registrarAtividade(editandoVendaId ? 'editou' : 'criou', 'venda', id, (p ? p.nome : '') + ' · ' + fmt(registro.valorTotal));
    const criadas = integDepoisDeGravar(id, registro, integ);
    estoqueAposGravarVenda(id, { ...(antesV || {}), ...registro });
    formAberto = false;
    const voltar = vendaVoltarPara === 'venda' ? vdVoltarPara : vendaVoltarPara;
    editandoVendaId = null;
    abrirVendaDetalhe(id, voltar);
    await integPerguntasDepois(id, registro, criadas);
  }
  $('venda-salvar').addEventListener('click', () => (formModo === 'orcamento' ? salvarOrcamentoForm() : salvarVenda()));
  $('back-venda-form').addEventListener('click', async () => {
    const temAlgo = formItens.some(i => (i.produto || '').trim() || i.custoUnit > 0);
    if (temAlgo && !vendaFormSalva && !(await confirmar(formModo === 'orcamento' ? 'Sair sem salvar este orçamento?' : 'Sair sem salvar esta venda?', 'Sair sem salvar'))) return;
    const voltar = vendaVoltarPara;
    editandoVendaId = null;
    formModo = 'venda'; orcEditandoId = null; formAberto = false;
    irParaDestinoVendas(voltar);
  });
  function irParaDestinoVendas(destino) {
    if (destino === 'venda') { renderVendaDetalhe(); showView('venda'); }
    else if (destino === 'orcamento') { renderOrcDetalhe(); showView('orcamento'); }
    else if (destino === 'orcamentos') { vendasAba = 'orcamentos'; abrirVendas(); }
    else if (destino === 'produtor' && currentProdutorId) { renderProdutorCompras(); showView('produtor'); }
    else { renderResumoVendas(); showView('vendas'); }
  }

  // ---- detalhe da venda ----
  function abrirVendaDetalhe(id, voltarPara) {
    vendaAbertaId = id;
    vdVoltarPara = voltarPara === 'produtor' ? 'produtor' : 'vendas';
    renderVendaDetalhe();
    showView('venda');
  }
  async function renderVendaDetalhe() {
    const v = vendas.find(x => x.id === vendaAbertaId) || vendasCanceladas().find(x => x.id === vendaAbertaId);
    $('vd-origem').hidden = true;
    $('vd-cancelada').hidden = true;
    if (!v) {
      $('vd-produtor').textContent = 'Venda não encontrada';
      $('vd-sub').textContent = 'Ela pode ter sido excluída em outro aparelho.';
      $('vd-itens').innerHTML = '';
      return;
    }
    const p = produtores.find(x => x.id === v.produtorId);
    $('vd-produtor').textContent = nomeProdutorDaVenda(v);
    $('vd-sub').textContent = (Number(v.numero) > 0 ? numVenda(v.numero) + ' · ' : '') + fmtDate(v.data) + (localDoProdutor(p) ? ' · ' + localDoProdutor(p) : '');
    const deOnde = v.origem === 'os' ? 'Veio da ' + numOS(v.osNumero) + ' ›' : v.origem === 'orcamento' ? 'Veio do ' + numOrc(v.orcamentoNumero) + ' ›' : v.origem === 'calculadora' ? 'Veio da Calculadora de lucro' : '';
    $('vd-origem').textContent = deOnde;
    $('vd-origem').hidden = !deOnde;
    $('vd-origem').disabled = v.origem === 'calculadora';
    $('vd-cancelada').textContent = v.cancelada ? 'Venda cancelada' + (v.canceladaMotivo ? ': ' + v.canceladaMotivo : '') + '. Não entra nos totais.' : '';
    $('vd-cancelada').hidden = !v.cancelada;

    const box = $('vd-itens');
    box.innerHTML = '';
    (v.itens || []).forEach(i => {
      const el = document.createElement('div');
      el.className = 'vd-item';
      el.innerHTML = '<div class="vd-item-nome"></div><div class="vd-item-sub"></div><div class="vd-item-valores"><span class="a"></span><span class="b"></span></div>';
      el.querySelector('.vd-item-nome').textContent = i.produto;
      el.querySelector('.vd-item-sub').textContent = [
        i.marcaNome || 'Sem marca',
        i.origem === 'fora' ? 'fora de SC' : 'dentro de SC',
        i.precoManual ? 'preço editado à mão' : veCustos() ? 'margem ' + fmtL(i.margem, 0) + '%' : ''
      ].filter(Boolean).join(' · ');
      el.querySelector('.a').textContent = fmtQtd(i.quantidade) + ' × ' + fmt(i.precoUnit);
      el.querySelector('.b').textContent = fmt((Number(i.quantidade) || 0) * (Number(i.precoUnit) || 0));
      integItemDetalhe(el, v, i);
      box.appendChild(el);
    });
    $('vd-total').textContent = fmt(v.valorTotal);
    $('vd-custo').textContent = fmt(v.custoTotal);
    $('vd-lucro').textContent = fmt(v.lucro);
    $('vd-margem').textContent = fmtPct1(v.margem);
    $('vd-pagamento').textContent = PAGAMENTOS[v.pagamento] || '—';
    $('vd-obs').hidden = !v.observacao;
    $('vd-obs').textContent = v.observacao || '';

    $('vd-comissao').innerHTML = '';
    $('vd-comissao').appendChild(document.createTextNode(fmt(v.comissaoValor)));
    const small = document.createElement('small');
    small.textContent = fmtL(v.comissaoPct, 1) + '% ' + textoBase(v.comissaoBase) +
      (v.comissaoRecebida ? ' · recebida' + (v.comissaoRecebidaEm ? ' em ' + fmtDate(v.comissaoRecebidaEm) : '') : ' · a receber');
    $('vd-comissao').appendChild(small);
    $('vd-com-toggle').querySelectorAll('button').forEach(b => {
      b.classList.toggle('active', (b.dataset.rec === 'sim') === !!v.comissaoRecebida);
    });
    $('vd-com-data-field').hidden = !v.comissaoRecebida;
    const mexeComissao = nivel('comissoes') >= 3 || (nivel('comissoes') >= 2 && v.criadoPor === viewerId);
    $('vd-com-toggle').querySelectorAll('button').forEach(b => { b.disabled = !mexeComissao; });
    $('vd-com-data').disabled = !mexeComissao;
    $('vd-editar').hidden = !!v.cancelada || !podeEditarRegistro('vendas', v.criadoPor);
    $('vd-excluir').hidden = !!v.cancelada || !podeEditarRegistro('vendas', v.criadoPor);
    $('vd-excluir').textContent = ehAdmin() ? 'Excluir esta venda' : 'Arquivar esta venda';
    if (document.activeElement !== $('vd-com-data')) $('vd-com-data').value = v.comissaoRecebidaEm || '';

    $('vd-autor').textContent = '';
    if (v.criadoPor) {
      try {
        const user = await claude.use('user');
        const ps = user ? await user.profiles([v.criadoPor]) : {};
        const nome = ps[v.criadoPor] && ps[v.criadoPor].name;
        if (vendaAbertaId === v.id) {
          $('vd-autor').textContent = 'Registrada por ' + (nome || 'alguém da equipe') + (v.criadoEm ? ' em ' + new Date(v.criadoEm).toLocaleDateString('pt-BR') : '');
        }
      } catch (e) {}
    }
  }
  $('vd-com-toggle').querySelectorAll('button').forEach(b => b.addEventListener('click', () => {
    if (!vendaAbertaId) return;
    const recebida = b.dataset.rec === 'sim';
    atualizarVenda(vendaAbertaId, { comissaoRecebida: recebida, comissaoRecebidaEm: recebida ? todayISO() : null });
    renderVendaDetalhe();
  }));
  $('vd-com-data').addEventListener('change', () => {
    if (!vendaAbertaId || !$('vd-com-data').value) return;
    atualizarVenda(vendaAbertaId, { comissaoRecebidaEm: $('vd-com-data').value });
    renderVendaDetalhe();
  });
  $('back-venda').addEventListener('click', () => irParaDestinoVendas(vdVoltarPara));
  $('vd-origem').addEventListener('click', () => {
    const v = vendasTodas.find(x => x.id === vendaAbertaId);
    if (!v) return;
    if (v.origem === 'orcamento' && v.orcamentoId) abrirOrcamento(v.orcamentoId, 'orcamentos');
    else if (v.origem === 'os' && produtores.some(p => p.id === v.produtorId)) openProdutor(v.produtorId, { aba: 'visitas', voltar: 'venda' });
  });
  $('vd-editar').addEventListener('click', () => {
    const v = vendas.find(x => x.id === vendaAbertaId);
    if (v) abrirFormVenda(v, { voltarPara: 'venda' });
  });
  $('vd-excluir').addEventListener('click', async () => {
    const v = vendas.find(x => x.id === vendaAbertaId);
    if (!v) return;
    const id = v.id;
    const r = await removerRegistro({ modulo: 'vendas', caminho: 'vendas/' + id, criadoPor: v.criadoPor,
      rotulo: 'a venda de ' + fmtDate(v.data) + ' para ' + nomeProdutorDaVenda(v), tipo: 'venda', alvoId: id, alvoNome: nomeProdutorDaVenda(v) + ' · ' + fmt(v.valorTotal) });
    if (!r) return;
    await integAoRemoverVenda(v);
    vendaAbertaId = null;
    irParaDestinoVendas(vdVoltarPara);
  });

  // ---- resumo do período ----
  $('vendas-mes').value = mesAtualISO();
  function vendasFiltradas() {
    const mes = $('vendas-mes').value;
    const vendedor = $('vendas-vendedor').value;
    return vendas.filter(v =>
      (!mes || (v.data || '').startsWith(mes)) &&
      (!vendedor || (vendedor === '__sem' ? !v.criadoPor : v.criadoPor === vendedor)));
  }
  function nomeVendedor(id) {
    if (!id) return 'Sem identificação';
    const u = (typeof usuariosLista !== 'undefined' ? usuariosLista : []).find(x => x.id === id);
    return (perfisVendas[id] && perfisVendas[id].name) || (u && u.apelido) || 'Sem nome';
  }
  async function renderResumoVendas() {
    const token = ++vendasRenderToken;
    const ids = [...new Set(vendas.map(v => v.criadoPor).filter(Boolean))];
    try {
      const user = await claude.use('user');
      if (user && ids.length) perfisVendas = await user.profiles(ids);
    } catch (e) {}
    if (token !== vendasRenderToken) return;

    // vendedores (quem registrou)
    const sel = $('vendas-vendedor');
    const atual = sel.value;
    sel.innerHTML = '<option value="">Todos</option>';
    ids.map(id => ({ id, nome: nomeVendedor(id) })).sort((a, b) => a.nome.localeCompare(b.nome)).forEach(x => {
      const o = document.createElement('option'); o.value = x.id; o.textContent = x.nome; sel.appendChild(o);
    });
    if (vendas.some(v => !v.criadoPor)) {
      const o = document.createElement('option'); o.value = '__sem'; o.textContent = 'Sem identificação'; sel.appendChild(o);
    }
    sel.value = [...sel.options].some(o => o.value === atual) ? atual : '';

    const lista = vendasFiltradas();
    const soma = (f) => lista.reduce((s, v) => s + (Number(f(v)) || 0), 0);
    const vendido = soma(v => v.valorTotal);
    const lucro = soma(v => v.lucro);
    $('vr-vendido').textContent = fmt(vendido);
    $('vr-qtd').textContent = lista.length + (lista.length === 1 ? ' venda' : ' vendas');
    $('vr-lucro').textContent = fmt(lucro);
    $('vr-margem').textContent = fmtPct1(vendido > 0 ? lucro / vendido : 0);
    $('vr-com-receber').textContent = fmt(soma(v => v.comissaoRecebida ? 0 : v.comissaoValor));
    $('vr-com-recebida').textContent = fmt(soma(v => v.comissaoRecebida ? v.comissaoValor : 0));
    $('cc-valor').textContent = fmtL(config.comissaoPct, 1) + '% ' + textoBase(config.comissaoBase);

    const box = $('vendas-lista');
    box.innerHTML = '';
    $('vendas-empty').hidden = lista.length > 0;
    $('vendas-empty').textContent = vendas.length ? 'Nenhuma venda neste período.' : 'Nenhuma venda registrada ainda. Toque em "+ Registrar venda".';
    $('vendas-rankings').hidden = lista.length === 0;
    lista.forEach(v => {
      const row = document.createElement('div');
      row.className = 'venda-row';
      row.setAttribute('role', 'button');
      row.tabIndex = 0;
      row.innerHTML = '<div class="vr-nome"></div><div class="vr-valor"></div><div class="vr-info"></div><div class="vr-com"></div>';
      row.querySelector('.vr-nome').textContent = nomeProdutorDaVenda(v);
      row.querySelector('.vr-valor').textContent = fmt(v.valorTotal);
      row.querySelector('.vr-info').textContent = [fmtDate(v.data), v.origem === 'os' || v.origem === 'orcamento' ? rotuloOrigemVenda(v) : '', PAGAMENTOS[v.pagamento] || '',
        v.criadoPor ? 'por ' + nomeVendedor(v.criadoPor) : ''].filter(Boolean).join(' · ');
      const com = row.querySelector('.vr-com');
      com.textContent = 'Comissão ' + fmt(v.comissaoValor) + (v.comissaoRecebida ? ' ✓' : '');
      com.dataset.perm = 'comissoes:1';
      com.classList.add(v.comissaoRecebida ? 'pago' : 'aberto');
      const abrir = () => abrirVendaDetalhe(v.id, 'vendas');
      row.addEventListener('click', abrir);
      row.addEventListener('keydown', e => { if (e.key === 'Enter') abrir(); });
      box.appendChild(row);
    });
    const mesFiltro = $('vendas-mes').value, vendFiltro = $('vendas-vendedor').value;
    vendasCanceladas().filter(v => (!mesFiltro || (v.data || '').startsWith(mesFiltro)) && (!vendFiltro || (vendFiltro === '__sem' ? !v.criadoPor : v.criadoPor === vendFiltro))).forEach(v => {
      const row = document.createElement('div');
      row.className = 'venda-row cancelada';
      row.setAttribute('role', 'button');
      row.tabIndex = 0;
      row.innerHTML = '<div class="vr-nome"></div><div class="vr-valor"></div><div class="vr-info"></div>';
      row.querySelector('.vr-nome').textContent = nomeProdutorDaVenda(v);
      row.querySelector('.vr-valor').textContent = fmt(v.valorTotal);
      row.querySelector('.vr-info').textContent = 'Cancelada · ' + fmtDate(v.data) + ' · ' + rotuloOrigemVenda(v);
      const abrir = () => abrirVendaDetalhe(v.id, 'vendas');
      row.addEventListener('click', abrir);
      row.addEventListener('keydown', e => { if (e.key === 'Enter') abrir(); });
      box.appendChild(row);
    });

    // rankings
    const porProduto = new Map();
    lista.forEach(v => (v.itens || []).forEach(i => {
      const k = normalizarBusca(i.produto);
      if (!k) return;
      const r = porProduto.get(k) || { nome: i.produto, qtd: 0, valor: 0 };
      r.qtd += Number(i.quantidade) || 0;
      r.valor += (Number(i.quantidade) || 0) * (Number(i.precoUnit) || 0);
      porProduto.set(k, r);
    }));
    const porProdutor = new Map();
    lista.forEach(v => {
      const r = porProdutor.get(v.produtorId) || { nome: nomeProdutorDaVenda(v), compras: 0, valor: 0 };
      r.compras += 1;
      r.valor += Number(v.valorTotal) || 0;
      porProdutor.set(v.produtorId, r);
    });
    desenharRanking($('rank-produtos'), [...porProduto.values()], r => fmtQtd(r.qtd) + (r.qtd === 1 ? ' unidade' : ' unidades'));
    desenharRanking($('rank-produtores'), [...porProdutor.values()], r => r.compras + (r.compras === 1 ? ' compra' : ' compras'));
  }
  function desenharRanking(box, itens, sub) {
    box.innerHTML = '';
    const top = itens.sort((a, b) => b.valor - a.valor).slice(0, 5);
    if (!top.length) {
      const v = document.createElement('div'); v.className = 'ranking-vazio'; v.textContent = 'Sem vendas no período.'; box.appendChild(v);
      return;
    }
    const max = top[0].valor || 1;
    top.forEach((r, i) => {
      const el = document.createElement('div');
      el.className = 'rank-item';
      el.innerHTML = '<div class="rank-nome"></div><div class="rank-valor"></div><div class="rank-barra"><span></span></div><div class="rank-sub"></div>';
      el.querySelector('.rank-nome').textContent = (i + 1) + '. ' + r.nome;
      el.querySelector('.rank-valor').textContent = fmt(r.valor);
      el.querySelector('.rank-barra span').style.width = Math.max(4, Math.round(r.valor / max * 100)) + '%';
      el.querySelector('.rank-sub').textContent = sub(r);
      box.appendChild(el);
    });
  }
  $('vendas-mes').addEventListener('change', renderResumoVendas);
  $('vendas-vendedor').addEventListener('change', renderResumoVendas);

  // ---- configurações (ICMS, margem padrão, comissão, limites do PMLS) ----
  // O botão "Comissão · Alterar" das vendas, o ⚙️ do banner e o da calculadora abrem esta mesma tela.
  let cfgBase = 'venda';
  function pintarCfgBase() {
    $('cfg-comissao-base').querySelectorAll('button').forEach(b => b.classList.toggle('active', b.dataset.base === cfgBase));
  }
  const CFG_CAMPOS = [
    ['cfg-icms-dentro', 'icmsDentro'], ['cfg-icms-fora', 'icmsFora'], ['cfg-margem', 'margemPadrao'],
    ['cfg-comissao-pct', 'comissaoPct'], ['cfg-limite-ccs', 'limiteCCS'], ['cfg-limite-cpp', 'limiteCPP']
  ];
  const CFG_LIMITES = {
    icmsDentro: [0, 100, 'o ICMS dentro de SC (de 0 a 100%)'], icmsFora: [0, 100, 'o ICMS fora de SC (de 0 a 100%)'],
    margemPadrao: [1, 79, 'a margem padrão (entre 1 e 79%)'], comissaoPct: [0, 100, 'a comissão (de 0 a 100%)'],
    limiteCCS: [1, 100000, 'o limite de CCS'], limiteCPP: [1, 100000, 'o limite de CPP']
  };
  async function abrirConfig(foco) {
    CFG_CAMPOS.forEach(([id, k]) => { $(id).value = numTxt(config[k]); });
    cfgBase = config.comissaoBase === 'lucro' ? 'lucro' : 'venda';
    pintarCfgBase();
    cfgOsVenda = config.osViraVenda !== false;
    pintarCfgOsVenda();
    // null = o app ainda não sabe: deixa tentar, e o banco recusa se não for Editor
    const pode = ehAdmin();
    $('cfg-aviso').hidden = pode;
    CFG_CAMPOS.forEach(([id]) => { $(id).disabled = !pode; });
    $('cfg-comissao-base').querySelectorAll('button').forEach(b => { b.disabled = !pode; });
    $('cfg-os-venda').querySelectorAll('button').forEach(b => { b.disabled = !pode; });
    $('cfg-comissao-save').hidden = !pode;
    $('cfg-comissao-cancel').textContent = pode ? 'Cancelar' : 'Fechar';
    $('cfg-autor').textContent = '';
    $('modal-comissao').hidden = false;
    if (pode && foco && $(foco)) setTimeout(() => { $(foco).focus(); $(foco).select(); }, 60);
    if (config.atualizadoPor || config.atualizadoEm) {
      let nome = '';
      try {
        const user = await claude.use('user');
        const ps = user && config.atualizadoPor ? await user.profiles([config.atualizadoPor]) : {};
        nome = (ps[config.atualizadoPor] && ps[config.atualizadoPor].name) || '';
      } catch (e) {}
      $('cfg-autor').textContent = 'Última alteração' + (nome ? ' por ' + nome : '') +
        (config.atualizadoEm ? ' em ' + new Date(config.atualizadoEm).toLocaleDateString('pt-BR') : '') + '.';
    }
  }
  document.querySelectorAll('.abrir-config').forEach(b => b.addEventListener('click', () => abrirConfig(b.dataset.foco)));
  $('btn-config-comissao').addEventListener('click', () => abrirConfig('cfg-comissao-pct'));
  $('cfg-comissao-base').querySelectorAll('button').forEach(b => b.addEventListener('click', () => { cfgBase = b.dataset.base; pintarCfgBase(); }));
  let cfgOsVenda = true;
  function pintarCfgOsVenda() { $('cfg-os-venda').querySelectorAll('button').forEach(b => { const on = (b.dataset.v === 'sim') === cfgOsVenda; b.classList.toggle('active', on); b.setAttribute('aria-pressed', on ? 'true' : 'false'); }); }
  $('cfg-os-venda').querySelectorAll('button').forEach(b => b.addEventListener('click', () => { cfgOsVenda = b.dataset.v === 'sim'; pintarCfgOsVenda(); }));
  $('cfg-comissao-cancel').addEventListener('click', () => { $('modal-comissao').hidden = true; });
  $('cfg-comissao-save').addEventListener('click', () => {
    const novo = {};
    for (const [id, k] of CFG_CAMPOS) {
      const txt = $(id).value.trim();
      const n = parseMoney(txt);
      const [min, max, nome] = CFG_LIMITES[k];
      if (txt === '' || !(n >= min) || n > max) { avisar('Confira ' + nome + '.').then(() => $(id).focus()); return; }
      novo[k] = n;
    }
    novo.comissaoBase = cfgBase;
    novo.osViraVenda = cfgOsVenda;
    novo.agendaMaxDia = config.agendaMaxDia;
    novo.agendaDias = config.agendaDias;
    novo.atualizadoPor = viewerId || null;
    novo.atualizadoEm = Date.now();
    gravar('set', 'config/geral', novo);
    registrarAtividade('editou', 'configuracoes');
    $('modal-comissao').hidden = true;
    if (!$('view-admin').hidden) setTimeout(renderAdmin, 50);
  });

  // ---- compras na ficha do produtor ----
  function renderProdutorCompras() {
    const pid = currentProdutorId;
    if (!pid) return;
    const compras = vendas.filter(v => v.produtorId === pid);
    const ano = todayISO().slice(0, 4);
    const totalAno = compras.filter(v => (v.data || '').startsWith(ano)).reduce((s, v) => s + (Number(v.valorTotal) || 0), 0);
    const abertos = orcVisiveis().filter(o => o.produtorId === pid && ORC_ABERTOS.includes(situacaoOrc(o)));
    $('produtor-compras-resumo').textContent = compras.length || abertos.length
      ? 'Comprou ' + fmt(totalAno) + ' em ' + ano + ' · ' + (compras.length === 1 ? '1 compra' : compras.length + ' compras') + (abertos.length ? ' · ' + (abertos.length === 1 ? '1 orçamento em aberto' : abertos.length + ' orçamentos em aberto') : '')
      : 'Nenhuma compra registrada ainda.';
    const linhas = compras.map(v => ({ data: v.data || '', valor: Number(v.valorTotal) || 0, de: rotuloOrigemVenda(v), itens: resumoItens(v.itens), abrir: () => abrirVendaDetalhe(v.id, 'produtor') }))
      .concat(abertos.map(o => ({ data: o.data || '', valor: Number(o.total) || 0, de: numOrc(o.numero) + ' · ' + ORC_SIT[situacaoOrc(o)], itens: resumoItens(o.itens), orc: true, abrir: () => abrirOrcamento(o.id, 'produtor') })))
      .sort((a, b) => b.data.localeCompare(a.data));
    const box = $('produtor-compras-lista');
    box.innerHTML = '';
    linhas.forEach(l => {
      const row = document.createElement('div');
      row.className = 'compra-row' + (l.orc ? ' compra-orc' : '');
      row.setAttribute('role', 'button');
      row.tabIndex = 0;
      row.innerHTML = '<span class="compra-data"></span><span class="compra-valor"></span><span class="compra-de"></span><span class="compra-itens"></span>';
      row.querySelector('.compra-data').textContent = fmtDate(l.data);
      row.querySelector('.compra-valor').textContent = fmt(l.valor);
      row.querySelector('.compra-de').textContent = l.de;
      row.querySelector('.compra-itens').textContent = l.itens;
      row.addEventListener('click', l.abrir);
      row.addEventListener('keydown', e => { if (e.key === 'Enter') l.abrir(); });
      box.appendChild(row);
    });
  }
  $('produtor-nova-venda').addEventListener('click', () => {
    if (currentProdutorId) abrirFormVenda(null, { produtorId: currentProdutorId, voltarPara: 'produtor' });
  });

