    if (!ids.length) { avisar('Nenhum produtor participa do PMLS ainda. Abra um produtor e marque "Participa: Sim".'); return; }
    exportarPmls(ids, 'ordenha360-pmls-' + todayISO() + '.xlsx', $('pmls-exportar-todos'));
