    if (a.feito) meta.push('Feita' + (a.feitoEm ? ' em ' + new Date(a.feitoEm).toLocaleDateString('pt-BR') : '') + (a.feitoPor ? ' por ' + nomePessoa(a.feitoPor) : ''));
