    if (token !== osFichaToken) return;
    perfisCache = { ...perfisCache, ...perfis };
    const ordem = v => { const st = statusOS(v); return st === 'andamento' ? 0 : st === 'agendada' ? 1 : st === 'aberta' ? 2 : 3; };
    const lista = visitas.slice().sort((a, b) => ordem(a) - ordem(b) || (ordem(a) < 3 ? dataRefOS(a).localeCompare(dataRefOS(b)) : dataRefOS(b).localeCompare(dataRefOS(a))) || (b.criadoEm || 0) - (a.criadoEm || 0));
