    if (c.abaixo) { av.hidden = false; av.textContent = 'Abaixo do padrão de ' + numTxt(c.m2) + ' m² por vaca: faltam ' + fmtN(Math.ceil(c.falta - 1e-9), 0) + ' m² para ' + vacas + ' vacas.'; }
    // modelo: com mais de um na tabela, a pessoa escolhe qual usar
