    $('ct-titulo').textContent = ctOpts.titulo || (ctOpts.onde === 'os' || ctOpts.onde === 'estoque' ? 'Adicionar peça' : 'Catálogo de produtos');
    $('ct-busca').value = '';
    $('ct-cats').innerHTML = '';
