    const todas = osVisiveis();
    const ab = todas.filter(osAtiva).length;
    $('os-sub').textContent = todas.length ? plural(todas.length, 'ordem de serviço', 'ordens de serviço') + ' · ' + plural(ab, 'em aberto', 'em aberto') : '';
