      grade([
        ['Data do serviço', st === 'agendada' ? 'Marcada para ' + fmtDate(v.agendadaPara) : fmtDate(v.data)], ['Categoria', CAT_LABEL[v.categoria] || '-'], ['Técnico', tecNome || '-'],
        ['Horário', v.horaInicio ? v.horaInicio + (v.horaFim ? ' às ' + v.horaFim : '') : '-'], ['Tempo total', fmtDur(v.duracaoMin) || '-'], ['Km rodados', temValor(v.km) ? numBR(v.km, 1) + ' km' : '-']
      ], 3);
