    if (foraFaixa(v, f)) return 'fora';
    if (f.min != null && f.max != null) { const m = (f.max - f.min) * ISO_ATENCAO; return v < f.min + m || v > f.max - m ? 'atencao' : 'ok'; }
    if (f.min != null) return v < f.min * (1 + ISO_ATENCAO) ? 'atencao' : 'ok';
