      if (Number(doc.horasPorOrdenha) > 0) c.horasPorOrdenha = Number(doc.horasPorOrdenha);
      if (Number(doc.resfriamentoMax) > 0) c.resfriamentoMax = Number(doc.resfriamentoMax);
      const r = doc.ref || {};
