      $('cf-ciclo-on').value = txtNum(a.cicloLigado);
      $('cf-ciclo-off').value = txtNum(a.cicloDesligado);
      cfSN = { comVentilacao: typeof a.comVentilacao === 'boolean' ? a.comVentilacao : null };
      pintarSimNao($('cf-com-vent'), cfSN);
