    const ult = osDoProdutorPrev(p.id).filter(o => osConcluida(o) && o.categoria === 'conforto' && o.conforto && o.conforto.ambiente).sort((a, b) => chaveOS(b).localeCompare(chaveOS(a)))[0];
    if (!ult) return [];
    const m = ult.conforto.ambiente;
    const cls = m.itu != null ? classeITU(m) : null;
    const frMax = (m.limites && m.limites.frMax) || cfgPrev.conforto.frMax;
    const partes = [];
    if (cls === 'laranja' || cls === 'vermelho') partes.push('ITU ' + fmtN(m.itu, 0) + ' (' + ITU_FAIXAS[cls].toLowerCase() + ')');
    if (m.fr != null && m.fr > frMax) partes.push('respiração ' + fmtN(m.fr, 0) + ' mov/min');
    if (!partes.length) return [];
    return [{ txt: 'Conforto (' + fmtDate(ult.data) + '): ' + partes.join(', '), cls: cls === 'vermelho' || (m.fr != null && m.fr > frMax) ? 'ruim' : 'atencao', ir: () => irParaOS(ult.id) }];
