  const PDF_ICONE_TITULO = [
    [/cadastro/i, 'user'], [/sistemas/i, 'settings'], [/preventiva|componentes/i, 'calendar-check'], [/laudo|teste/i, 'flask-conical'],
    [/resfriador/i, 'snowflake'], [/conforto/i, 'fan'], [/ordens|visitas|manuten|servi[cç]o|equipamentos/i, 'wrench'], [/chamado/i, 'phone'],
    [/defeito/i, 'triangle-alert'], [/pe[cç]as/i, 'package'], [/fotos/i, 'camera'], [/cancelad/i, 'ban'], [/leite|m[eé]dia/i, 'milk'],
    [/qualidade|pmls|coleta|an[aá]lise/i, 'badge-check'], [/veterin|sanidade|reprodu|atendimento|animais/i, 'stethoscope'], [/nutri|dieta|lote/i, 'wheat'],
    [/compras|vendas|comercial/i, 'shopping-bag'], [/encaminhamento|tarefa/i, 'forward'], [/checklist|plano de a[cç][aã]o/i, 'list-checks']
  ];
  const cacheIconePdf = {};
  function iconePdf(nome, cor) {
    const chave = nome + '|' + cor.join(',');
    if (cacheIconePdf[chave] !== undefined) return Promise.resolve(cacheIconePdf[chave]);
    const corpo = ICONES_PDF[nome];
    if (!corpo) return Promise.resolve(null);
    const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96" viewBox="0 0 24 24" fill="none" stroke="rgb(' + cor.join(',') + ')" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + corpo + '</svg>';
    return new Promise(res => {
      const img = new Image();
      img.onload = () => {
        try { const c = document.createElement('canvas'); c.width = 96; c.height = 96; c.getContext('2d').drawImage(img, 0, 0, 96, 96); cacheIconePdf[chave] = c.toDataURL('image/png'); }
        catch (e) { cacheIconePdf[chave] = null; }
        res(cacheIconePdf[chave]);
      };
      img.onerror = () => { cacheIconePdf[chave] = null; res(null); };
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    });
  }
  // carrega de uma vez os ícones que os títulos podem usar
  async function prepararIconesPdf(cor) {
    const nomes = [...new Set(PDF_ICONE_TITULO.map(x => x[1]).concat(['wrench', 'user']))];
    const out = {};
    await Promise.all(nomes.map(async n => { out[n] = await iconePdf(n, cor); }));
    return titulo => { const m = PDF_ICONE_TITULO.find(([re]) => re.test(titulo)); return m ? out[m[1]] : null; };
  }


