  // ---------- faixas no topo (dados de demonstração / visão do produtor) ----------
  function apFaixas() {
    const prod = document.body.classList.contains('modo-produtor');
    const tem = DEMO_ATIVO || prod;
    $('fx-demo').hidden = !DEMO_ATIVO;
    $('fx-prod').hidden = !prod || DEMO_ATIVO;   // na demonstração a faixa é uma só
    if (DEMO_ATIVO) {
      const c = demoComo ? demoComoInfo(demoComo) : null;
      let txt = 'Dados de demonstração';
      if (c) {
        txt = 'Demonstração · Entrando como ' + c.nome;
      }
      $('fx-demo-txt').textContent = txt;
      $('fx-demo-desligar').textContent = c ? 'Trocar' : 'Desligar';
      $('fx-demo-desligar').setAttribute('aria-label', c ? 'Trocar de setor' : 'Desligar o modo demonstração');
      $('fx-demo-ico').setAttribute('href', '#i-' + (c ? c.ic : 'presentation'));
      $('fx-demo').dataset.como = c ? c.id : '';
    }
    $('fx').hidden = !tem;
    document.documentElement.classList.toggle('com-faixas', tem);
    const medir = () => document.documentElement.style.setProperty('--fx-h', (tem ? Math.round($('fx').getBoundingClientRect().height) : 0) + 'px');
    medir();
    requestAnimationFrame(medir);
  }
  window.addEventListener('resize', () => { if (!$('fx').hidden) apFaixas(); });
  $('fx-demo-desligar').addEventListener('click', () => { if (DEMO_ATIVO && demoComo) integTrocar(); else demoDesligar(); });
  $('fx-prod-sair').addEventListener('click', () => pdSair());

  // ---------- modo demonstração ----------
  const DEMO_SUBCOLS = ['equipamentos', 'visitas', 'medias', 'coletas', 'fotos', 'animais', 'lotes', 'atendimentos', 'sanidade', 'reproducao',
    'nutricao', 'dietas', 'acoes', 'ccsVacas', 'checklists'];
  const DEMO_TOPO = ['demo_ordens', 'demo_encaminhamentos', 'demo_vendas', 'demo_calculos', 'demo_orcamentos', 'demo_anotacoes', 'demo_agenda-tokens'];
  function nomeArquivoDemo(n) { return DEMO_ATIVO ? 'DEMONSTRACAO-' + n : n; }
  // PDFs gerados no modo demonstração saem marcados em todas as páginas
  function carimboDemoPdf(doc) {
    const original = doc.output.bind(doc);
    doc.output = function () {
      if (!doc.__carimbado) {
        doc.__carimbado = true;
        try {
          const n = doc.getNumberOfPages();
          for (let i = 1; i <= n; i++) {
            doc.setPage(i);
            const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight();
            doc.setFont(doc.__fonte || 'helvetica', 'bold');
            doc.setFontSize(7.5);
            doc.setTextColor(176, 116, 0);
            doc.text('DADOS DE DEMONSTRAÇÃO (FICTÍCIOS)', W / 2, H - 6.5, { align: 'center' });
          }
        } catch (e) {}
      }
      return original.apply(doc, arguments);
    };
  }
  function demoPrep(tit, pct, sub) {
    const box = $('demo-prep');
    if (tit == null) { box.hidden = true; return; }
    box.hidden = false;
    $('demo-prep-tit').textContent = tit;
    $('demo-prep-barra').style.width = Math.max(4, Math.round((pct || 0) * 100)) + '%';
    if (sub != null) $('demo-prep-sub').textContent = sub;
  }
  function renderDemoAdmin() {
    $('adm-demo-st').textContent = DEMO_ATIVO ? 'Ligado' : 'Desligado';
    $('adm-demo-st').classList.toggle('on', DEMO_ATIVO);
    $('adm-demo-ligar-txt').textContent = DEMO_ATIVO ? 'Desligar modo demonstração' : 'Ligar modo demonstração';
    $('adm-demo-ligar').classList.toggle('adm-demo-off', DEMO_ATIVO);
    $('adm-demo-recriar').hidden = !DEMO_ATIVO;
  }
  function demoRecarregar(ligado) {
    try { if (ligado) localStorage.setItem(DEMO_CHAVE, '1'); else localStorage.removeItem(DEMO_CHAVE); } catch (e) {}
    demoPrep(ligado ? 'Abrindo o modo demonstração…' : 'Voltando aos dados reais…', 1, '');
    setTimeout(() => { try { location.reload(); } catch (e) {} }, 350);
  }
  function limparLocalDemo() {
    const ks = [];
    try { for (let i = 0; i < localStorage.length; i++) ks.push(localStorage.key(i)); } catch (e) {}
    ks.forEach(k => { if (k && (k.startsWith('auriverde_demo_espelho_') || k === 'auriverde_demo_fila_envio' || k === 'auriverde_demo_rota')) apagarLS(k); });
  }
  async function demoMarca() {
    const s = await comPrazo(dbBruto.doc('demo_sistema/demo').get(), 15000);
    return s && s.exists ? s.data() : null;
  }
  async function demoLigar() {
    if (!ehAdmin()) return;
    if (!dbBruto) { avisar('Para ligar o modo demonstração o app precisa estar conectado ao banco (internet).'); return; }
    const ok = await abrirDialogo('Ligar o modo demonstração neste aparelho? O app passa a mostrar só dados fictícios até você desligar. Os dados reais continuam guardados e não se misturam.', { ok: 'Ligar', cancelar: 'Cancelar' });
    if (!ok) return;
    try {
      demoPrep('Preparando os dados de demonstração…', 0.02, 'Isso leva alguns segundos.');
      const marca = await demoMarca();
      // dados de outro dia são recriados, para as datas (visitas marcadas, preventivas) valerem a partir de hoje
      if (!marca || marca.geradoEm !== todayISO()) { await demoApagarDados(); limparLocalDemo(); await demoCriarDados(); }
      demoRecarregar(true);
    } catch (e) {
      demoPrep(null);
      avisar('Não consegui preparar os dados de demonstração agora. Confira a internet e tente de novo.');
    }
  }
  async function demoDesligar() {
    const ok = await abrirDialogo('Desligar o modo demonstração e voltar aos dados reais?', { ok: 'Desligar', cancelar: 'Cancelar' });
    if (!ok) return;
    demoRecarregar(false);
  }
  async function demoRecriar() {
    if (!ehAdmin() || !dbBruto) return;
    const ok = await abrirDialogo('Recriar os dados de demonstração? Tudo o que foi feito no modo demonstração volta ao estado inicial, com datas a partir de hoje. Os dados reais não são tocados.', { ok: 'Recriar', cancelar: 'Cancelar' });
    if (!ok) return;
    try {
      demoPrep('Recriando os dados de demonstração…', 0.02, 'Isso leva alguns segundos.');
      await demoApagarDados();
      limparLocalDemo();
      await demoCriarDados();
      demoRecarregar(true);
    } catch (e) {
      demoPrep(null);
      avisar('Não consegui recriar os dados agora. Confira a internet e tente de novo.');
    }
  }
  $('adm-demo-ligar').addEventListener('click', () => { if (DEMO_ATIVO) demoDesligar(); else demoLigar(); });
  $('adm-demo-recriar').addEventListener('click', () => demoRecriar());

  // grava em lotes pequenos direto nas coleções demo_* (nunca passa pela fila dos dados reais)
  async function demoEscrever(ops, de, ate) {
    const total = ops.length;
    for (let i = 0; i < total; i += 8) {
      await Promise.all(ops.slice(i, i + 8).map(([tipo, caminho, dados]) => {
        const ref = dbBruto.doc(caminho);
        return comPrazo(tipo === 'delete' ? ref.delete() : ref.set(dados), 20000);
      }));
      demoPrep($('demo-prep-tit').textContent, de + (ate - de) * Math.min(1, (i + 8) / Math.max(1, total)));
    }
  }
  async function demoListar(colecao) {
    try { const s = await comPrazo(dbBruto.collection(colecao).get(), 20000); return s.docs.map(d => d.id); } catch (e) { return []; }
  }
  async function demoApagarDados() {
    const alvos = [];
    const pids = await demoListar('demo_produtores');
    for (const pid of pids) {
      const listas = await Promise.all(DEMO_SUBCOLS.map(sc => demoListar('demo_produtores/' + pid + '/' + sc).then(ids => ids.map(id => 'demo_produtores/' + pid + '/' + sc + '/' + id))));
      listas.forEach(l => alvos.push(...l));
      alvos.push('demo_produtores/' + pid);
    }
    for (const c of DEMO_TOPO) (await demoListar(c)).forEach(id => alvos.push(c + '/' + id));
    const uids = [...new Set([viewerId, ...usuariosLista.map(u => u.id)].filter(Boolean))];
    for (const u of uids) (await demoListar('demo_atividades/' + u + '/itens')).forEach(id => alvos.push('demo_atividades/' + u + '/itens/' + id));
    for (const u of uids) for (const sc of ['itens', 'movs']) (await demoListar('demo_estoque/' + u + '/' + sc)).forEach(id => alvos.push('demo_estoque/' + u + '/' + sc + '/' + id));
    alvos.push('demo_sistema/migracaoOS', 'demo_sistema/demo');
    demoPrep('Limpando a demonstração anterior…', 0.05);
    await demoEscrever(alvos.map(c => ['delete', c]), 0.05, 0.3);
  }

